    /// BUILD 199 — the never-interview list, written down so it survives
    /// the next person who adds a tool. These are answered by the ladder
    /// long before anything here runs, and nothing in the registry may
    /// ever claim them.
    static let neverInterviewed: Set<String> = [
        "emergency", "sos", "stop", "cancel", "close", "chappy reset",
    ]

    static func tool(id: String) -> ChappyTool? { tools.first { $0.id == id } }

    /// AUDIT (200): every required slot present. Used to decide whether a
    /// confirmed plan can run straight away or still owes questions —
    /// without it, saying "yes" to "did you mean somewhere to eat?" ran a
    /// search for the word "food" instead of asking what he wanted.
    static func isComplete(_ t: ChappyTool, _ values: [String: String]) -> Bool {
        t.slots.allSatisfy { $0.optional || !(values[$0.id] ?? "").isEmpty }
    }

    static func tool(forScreen n: Notification.Name?) -> ChappyTool? {
        guard let n else { return nil }
        // BUILD 199: navigate and food have no screen of their own, so
        // the matcher hands over a placeholder name. Map it here rather
        // than giving them a screen they don't have.
        if n == .chappyOpenFood { return tool(id: "food") }
        if n == .chappyOpenAttractions { return tool(id: "attractions") }
        if n == .chappyOpenNavigate { return tool(id: "navigate") }
        return tools.first { $0.screen == n }
    }
}

// =====================================================================
// MARK: - CHAPPY FLOW (Build 197) — THE INTERVIEW
// =====================================================================
//
// One engine, every tool. It asks for what is missing and nothing else,
// takes answers in any order, fills what it already knows from the
// profile, and gets out of the way the moment the sentence stops being
// an answer.
//
// Three rules it will not bend:
//
//   * It never invents a value. A vague date gets another question, not
//     a guess — a flight search built on the wrong day is worse than an
//     extra sentence.
//   * It never traps you. Any recognised command, and any of the exit
//     words, ends the interview immediately.
//   * It expires. Ninety seconds of silence and the interview is over,
//     because a half-finished conversation you have forgotten about is
//     a trap of a different kind.
//
final class ChappyFlow {

    static let shared = ChappyFlow()
    private init() {}

    enum Outcome {
        case say(String)
        case finished(String, ChappyTool, [String: String])
        case cancelled(String)
        /// Not an answer at all — hand it back to the router untouched.
        case passthrough
    }

    private(set) var tool: ChappyTool?
    private(set) var values: [String: String] = [:]
    private var currentSlot: String?
    private var lastTouched = Date.distantPast
    private var misses = 0
    /// BUILD 202: the slot whose guessed value is waiting on a yes.
    private var awaitingConfirm: String?

    private static let lifetime: TimeInterval = 90

    var isActive: Bool {
        guard tool != nil else { return false }
        if Date().timeIntervalSince(lastTouched) < Self.lifetime { return true }
        // BUILD 203: the window closed. Park it on the way out rather than
        // letting it evaporate — this is case 4, and it is the one that
        // felt worst.
        park()
        return false
    }

    private static let exits: Set<String> = [
        "stop", "cancel", "never mind", "nevermind", "forget it", "leave it",
        "quit", "done", "that's enough", "thats enough", "not now", "later",
    ]

    // ---------------------------------------------------------------- start
    func start(_ t: ChappyTool, from utterance: String) -> String {
        // AUDIT (199): the never-interview list existed as a comment with
        // a Set attached and nothing ever read it. Documentation that the
        // code does not consult is a promise, not a guarantee.
        let bare = utterance.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: " ,.:;!?-"))
        if ChappyRegistry.neverInterviewed.contains(bare) {
            cancel()
            return ""
        }
        tool = t
        values = [:]
        misses = 0
        lastTouched = Date()

        // Anything already said counts. "Chappy, flights to Bali on the
        // seventh" should not then be asked where he's going.
        harvest(utterance, into: t)
        applyPrefills(t)

        guard let next = nextSlot(t) else {
            // Everything was already known. Say it back and act — this
            // path used to announce "running it" and then run nothing.
            let v = values
            tool = nil; currentSlot = nil; values = [:]
            deliver(tool: t, values: v)
            return "\(t.opening) \(Self.summary(t, v)) Running it."
        }
        currentSlot = next.id
        return "\(t.opening) \(next.ask)"
    }

    /// BUILD 198: start an interview that already knows some answers —
    /// the planner having lifted them out of the sentence. Same rules;
    /// it simply has less to ask.
    func startWith(_ t: ChappyTool, values known: [String: String]) -> String {
        tool = t
        values = [:]
        misses = 0
        lastTouched = Date()
        for (k, v) in known where t.slots.contains(where: { $0.id == k }) {
            // An airport arrives as a city name from the model and has to
            // survive our own table before it counts.
            if t.slots.first(where: { $0.id == k })?.kind == .airport {
                if let a = ChappyPorts.resolve(place: v) { values[k] = a.iata }
            } else {
                values[k] = v
            }
        }
        applyPrefills(t)
        guard let next = nextSlot(t) else {
            let v = values
            tool = nil; currentSlot = nil; values = [:]
            deliver(tool: t, values: v)
            var line = "\(Self.summary(t, v)) Running it."
            if let n = ChappyNext.after(t.id, values: v) { line += " \(n)" }
            return line
        }
        currentSlot = next.id
        return "\(t.opening) \(next.ask)"
    }

    // ---------------------------------------------------------------- answer
    func answer(_ raw: String) async -> Outcome {
        guard let t = tool else { return .passthrough }
        let c = raw.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: " ,.:;!?-"))

        if Self.exits.contains(c) {
            // An explicit exit is a decision. Nothing is kept.
            dropEverything()
            return .cancelled("Dropped it.")
        }
        // A different screen named out loud is a new instruction, not an
        // answer. Let the router have it — being mid-interview must never
        // mean you cannot change your mind.
        if let other = ChappyTiles.match(c), ChappyRegistry.tool(forScreen: other.note)?.id != t.id {
            // BUILD 203: parked, not binned. He changed subject; he did not
            // say the first thing no longer matters.
            park()
            return .passthrough
        }

        lastTouched = Date()

        // BUILD 200 — §7's missing half: CHANGING YOUR MIND.
        //
        // The document asks for "same as last time", "add one more
        // person" and "change the destination" without restarting the
        // workflow. Until now every one of those was treated as an answer
        // to whatever question was on the table, which is how a
        // conversation turns into a form you cannot edit.
        if let out = amend(c, t) { return out }

        guard let slotID = currentSlot, let slot = t.slots.first(where: { $0.id == slotID }) else {
            cancel()
            return .passthrough
        }

        var got = ChappySlots.parse(raw, as: slot.kind)
        // Everything else he happened to mention lands too.
        harvest(raw, into: t, excluding: slot.id)

        var fromModel = false
        if got == nil, misses >= 1 {
            got = await ChappySlots.modelParse(raw, as: slot.kind, question: slot.ask)
            fromModel = got != nil
        }

        // BUILD 202 — Alexa's rule, and it is a good one: confirm a slot
        // only when getting it wrong would be expensive. Rather than a
        // fixed list of "important" slots, confirm the ones that were
        // GUESSED — a local parse of "Brisbane" or "the seventh" is
        // deterministic and does not need checking, and a model's reading
        // of "early September-ish" very much does.
        if fromModel, let v = got, slot.kind == .date || slot.kind == .airport {
            let readable = slot.kind == .date ? ChappySlots.spokenDate(v)
                                              : (ChappyPorts.byIATA(v)?.city ?? v)
            values[slot.id] = v
            currentSlot = slot.id
            awaitingConfirm = slot.id
            return .say("\(readable) — right?")
        }

        // The answer to that confirmation.
        if let pendingSlot = awaitingConfirm {
            awaitingConfirm = nil
            if ChappySlots.parse(raw, as: .yesNo) == "no" {
                values[pendingSlot] = nil
                currentSlot = pendingSlot
                misses = 0
                return .say(t.slots.first(where: { $0.id == pendingSlot })
                                .map { Self.retry($0, attempt: 2) } ?? "Again?")
            }
            if ChappySlots.parse(raw, as: .yesNo) == "yes" { return advance(t) }
            // Not yes or no — treat it as a fresh answer to the same slot.
        }

        guard let value = got else {
            misses += 1
            if slot.optional {
                values[slot.id] = ""          // offered once, never chased
                return advance(t)
            }
            if misses >= 3 {
                cancel()
                return .cancelled("Let's come back to that one.")
            }
            return .say(Self.retry(slot, attempt: misses))
        }

        misses = 0
        values[slot.id] = value
        return advance(t)
    }

    /// The words people say when they are editing rather than answering.
    /// Nil means "this is a normal answer, carry on".
    private func amend(_ c: String, _ t: ChappyTool) -> Outcome? {

        // "same as usual" — take every default there is and stop asking
        // about the optional ones. This is the single most common thing a
        // regular traveller says and it used to be parsed as a place name.
        if ["same", "same as usual", "as usual", "usual", "same as last time",
            "the usual", "like last time", "same again"].contains(c) {
            applyPrefills(t)
            for slot in t.slots where slot.optional && values[slot.id] == nil {
                values[slot.id] = ""
            }
            return advance(t)
        }

        if ["start again", "start over", "from the top", "scrap that"].contains(c) {
            let again = t
            cancel()
            return .say(startWith(again, values: [:]))
        }

        // "add one more", "one less", "make it four"
        if c.contains("one more") || c.contains("another one") || c.contains("one less")
            || c.hasPrefix("make it ") || c.hasPrefix("change it to ") {
            if let partySlot = t.slots.first(where: { $0.kind == .count }) {
                let current = Int(values[partySlot.id] ?? "") ?? ChappyProfileLite.party
                var updated: Int?
                if c.contains("one more") || c.contains("another one") { updated = current + 1 }
                if c.contains("one less"), current > 1 { updated = current - 1 }
                if let n = updated {
                    values[partySlot.id] = String(n)
                    // AUDIT (200): this returned "3 of you." plus whatever
                    // nextAsk gave, and nextAsk returns an empty string when
                    // there is nothing left to ask — so amending the last
                    // slot acknowledged the change and then sat there
                    // forever. Acknowledge, then carry on properly.
                    switch advance(t) {
                    case .say(let q):
                        return .say("\(n) of you. \(q)")
                    case .finished(let line, let tool, let vals):
                        return .finished("\(n) of you. \(line)", tool, vals)
                    case let other:
                        return other
                    }
                }
            }
            // "make it X" with no count slot is a correction to whatever is
            // on the table — fall through and let it be parsed as one.
            return nil
        }

        // "change the destination to Bali", "make the date the ninth"
        let named: [(String, [String])] = [
            ("to", ["destination", "where we're going", "where im going", "where i'm going"]),
            ("from", ["origin", "departure", "where we're leaving", "start"]),
            ("when", ["date", "day", "when"]),
            ("nights", ["length", "how long", "nights"]),
            ("party", ["people", "party", "how many", "travellers"]),
            ("budget", ["budget", "money", "spend"]),
            ("country", ["country"]),
            ("language", ["language"]),
        ]
        guard c.hasPrefix("change") || c.hasPrefix("actually") || c.hasPrefix("no ")
                || c.hasPrefix("no,") || c.hasPrefix("i meant") else { return nil }

        for (slotID, words) in named {
            guard t.slots.contains(where: { $0.id == slotID }),
                  words.contains(where: { c.contains($0) }) else { continue }
            guard let slot = t.slots.first(where: { $0.id == slotID }) else { continue }
            // Everything after the last "to" is the new value; failing that,
            // hand the whole sentence to the parser and let it find one.
            let tailStart = c.range(of: " to ", options: .backwards)?.upperBound
            let tail = tailStart.map { String(c[$0...]) } ?? c
            if let v = ChappySlots.parse(tail, as: slot.kind) {
                values[slotID] = v
                currentSlot = nil
                return advance(t)
            }
            values[slotID] = nil
            currentSlot = slotID
            return .say(slot.ask)
        }

        // "actually, Bali" — a correction to the slot currently on the
        // table, with the correction word stripped off the front.
        if let slotID = currentSlot, let slot = t.slots.first(where: { $0.id == slotID }) {
            var tail = c
            for lead in ["actually ", "no, ", "no ", "i meant ", "change it to ", "change "] {
                if tail.hasPrefix(lead) { tail = String(tail.dropFirst(lead.count)); break }
            }
            if let v = ChappySlots.parse(tail, as: slot.kind) {
                values[slotID] = v
                return advance(t)
            }
        }
        return nil
    }

    private func advance(_ t: ChappyTool) -> Outcome {
        guard let next = nextSlot(t) else {
            let v = values
            // BUILD 198 — §9. ONE suggestion, only when it follows
            // obviously, never the same one twice running.
            var line = "\(Self.summary(t, v)) Running it."
            if let n = ChappyNext.after(t.id, values: v) { line += " \(n)" }
            tool = nil; currentSlot = nil; values = [:]
            return .finished(line, t, v)
        }
        currentSlot = next.id
        return .say(next.ask)
    }

    // BUILD 203 — SOMEWHERE TO PUT AN INTERRUPTED CONVERSATION.
    //
    // §12 asks for enough state to resume an interrupted workflow. Three
    // of the fifteen heavy workflows died for want of exactly this, and
    // the worst of them is the ordinary one: you start a flight search,
    // you get on a scooter, ninety seconds pass, and the answer you give
    // lands in an empty room.
    //
    // Parked, not saved. It lives for twenty minutes in memory and never
    // touches disk — a half-finished conversation you have forgotten
    // about is its own kind of trap, and one you find again next week is
    // worse than none.
    private struct Parked {
        let tool: ChappyTool
        let values: [String: String]
        let slot: String?
        let at: Date
    }
    private var parked: Parked?
    private static let parkLife: TimeInterval = 1200

    /// True when there is something to come back to.
    var hasParked: Bool {
        guard let p = parked else { return false }
        return Date().timeIntervalSince(p.at) < Self.parkLife
    }

    var parkedTitle: String? { hasParked ? parked?.tool.title : nil }

    /// Set aside rather than thrown away. Called when something else
    /// takes over and when the window expires — NOT when he says "never
    /// mind", because that is a decision and it deserves respect.
    func park() {
        guard let t = tool, !values.isEmpty else { cancel(); return }
        parked = Parked(tool: t, values: values, slot: currentSlot, at: Date())
        tool = nil; currentSlot = nil; values = [:]; misses = 0
        awaitingConfirm = nil
        lastTouched = .distantPast
    }

    /// Pick it up where it stopped. Returns what to say, or nil.
    func resume() -> String? {
        guard hasParked, let p = parked else { return nil }
        parked = nil
        tool = p.tool
        values = p.values
        currentSlot = p.slot
        misses = 0
        awaitingConfirm = nil
        lastTouched = Date()
        guard let next = nextSlot(p.tool) else {
            let v = values
            tool = nil; currentSlot = nil; values = [:]
            deliver(tool: p.tool, values: v)
            return "Picking that back up. \(Self.summary(p.tool, v)) Running it."
        }
        currentSlot = next.id
        // Say what it already has, so he is not made to remember it.
        let so_far = Self.summary(p.tool, values)
        return "Picking that back up — \(so_far) \(next.ask)"
    }

    /// Resume only if the parked interview is the tool being asked for.
    /// Saying "flights" again should continue, not start over.
    func resumeIfMatches(_ t: ChappyTool) -> String? {
        guard hasParked, parked?.tool.id == t.id else { return nil }
        return resume()
    }

    func cancel() {
        tool = nil; currentSlot = nil; values = [:]; misses = 0
        awaitingConfirm = nil
        lastTouched = .distantPast
    }

    /// An explicit "never mind" clears the park too. He said no.
    func dropEverything() {
        parked = nil
        cancel()
    }

    // ---------------------------------------------------------------- helpers
    private func nextSlot(_ t: ChappyTool) -> ChappySlot? {
        t.slots.first { values[$0.id] == nil }
    }

    /// Pull anything the sentence already answers. Only fills slots that
    /// are still empty, and only when the parse is unambiguous — a
    /// harvest that guesses is worse than no harvest at all.
    private func harvest(_ utterance: String, into t: ChappyTool, excluding: String? = nil) {
        // "brisbane to bali" — the word "to" is the only reliable divider
        // in a spoken route, and it is worth handling explicitly because
        // it is how everyone says it.
        let low = utterance.lowercased()
        if t.slots.contains(where: { $0.id == "from" }), values["from"] == nil,
           let r = low.range(of: " to ") {
            let head = String(low[low.startIndex..<r.lowerBound])
            let tail = String(low[r.upperBound...])
            if let a = ChappySlots.parse(head, as: .airport) { values["from"] = a }
            if values["to"] == nil, let b = ChappySlots.parse(tail, as: .airport) { values["to"] = b }
        }
        for slot in t.slots where values[slot.id] == nil && slot.id != excluding {
            switch slot.kind {
            case .date, .nights, .count, .money, .language:
                if let v = ChappySlots.parse(utterance, as: slot.kind) { values[slot.id] = v }
            default:
                break   // never harvest free text — too easy to be wrong
            }
        }
    }

    private func applyPrefills(_ t: ChappyTool) {
        for slot in t.slots where values[slot.id] == nil {
            switch slot.prefill {
            case .none: break
            case .homeAirport:
                let air = ChappyProfileLite.homeAirport
                let city = ChappyProfileLite.homeCity
                if !air.isEmpty { values[slot.id] = air }
                else if !city.isEmpty,
                        let a = ChappyPorts.resolve(place: city) { values[slot.id] = a.iata }
            case .party:
                values[slot.id] = String(ChappyProfileLite.party)
            case .oneWay:
                values[slot.id] = "yes"
            case .homeCurrency:
                values[slot.id] = ChappyProfileLite.homeCurrency
            case .cabin:
                let v = ChappyProfileLite.data.cabinPreference ?? ""
                if !v.isEmpty { values[slot.id] = v }
            case .style:
                let v = ChappyProfileLite.data.styleLevel ?? ""
                if !v.isEmpty { values[slot.id] = v }
            case .diet:
                let v = ChappyProfileLite.data.dietary ?? ""
                if !v.isEmpty { values[slot.id] = v }
            case .airlines:
                let v = ChappyProfileLite.data.preferredAirlines ?? []
                if !v.isEmpty { values[slot.id] = v.joined(separator: ", ") }
            case .nationality:
                let v = ChappyProfileLite.data.nationality ?? ""
                if !v.isEmpty { values[slot.id] = v }
            }
        }
    }

    /// A second attempt should not be the same question louder. It should
    /// be a narrower question.
    private static func retry(_ slot: ChappySlot, attempt: Int) -> String {
        switch slot.kind {
        case .date:     return attempt == 1 ? "Which day exactly?" : "Give me a date — the seventh of September, say."
        case .airport:  return attempt == 1 ? "Which city?" : "Say the city or the airport code."
        case .count:    return "How many people?"
        case .nights:   return "How many nights?"
        case .money:    return "Roughly how much?"
        case .yesNo:    return "Yes or no?"
        case .language: return "Which language?"
        case .mode:     return "Walking, riding, or a car?"
        case .priceBand:return "Cheap, middling, or somewhere nice?"
        case .span:     return "Over what — a month, three months, a year?"
        default:        return slot.ask
        }
    }

    /// Read the whole thing back before acting. Cheap, and it catches a
    /// misheard destination before it becomes a search for the wrong
    /// country.
    static func summary(_ t: ChappyTool, _ v: [String: String]) -> String {
        switch t.id {
        case "flights":
            var bits: [String] = []
            // Read back CITIES, not codes. "BNE to DPS" is a booking
            // reference; "Brisbane to Bali" is what he said and what he
            // can check. The codes still go to the search.
            if let f = v["from"], let to = v["to"] {
                let fc = ChappyPorts.byIATA(f)?.city ?? f
                let tc = ChappyPorts.byIATA(to)?.city ?? to
                bits.append("\(fc) to \(tc)")
            }
            if let d = v["when"], !d.isEmpty { bits.append(ChappySlots.spokenDate(d)) }
            if let p = v["party"], p != "1" { bits.append("\(p) of you") }
            if v["oneway"] == "yes" { bits.append("one-way") }
            return bits.isEmpty ? "Flights." : bits.joined(separator: ", ") + "."
        case "travel":
            var bits: [String] = []
            if let to = v["to"] { bits.append(to) }
            if let n = v["nights"], !n.isEmpty { bits.append("\(n) nights") }
            if let b = v["budget"], !b.isEmpty { bits.append("around \(b)") }
            return bits.isEmpty ? "Travel desk." : bits.joined(separator: ", ") + "."
        case "reminders":
            let what = v["what"] ?? "that"
            let when = v["when"].map { ChappySlots.spokenDate($0) } ?? "later"
            return "Remind you to \(what.lowercased()) on \(when)."
        case "navigate":
            return "\(v["to"] ?? "there"), \(v["mode"] ?? "walking")."
        case "food", "attractions":
            return [v["price"], v["kind"]].compactMap { $0 }.joined(separator: " ") + "."
        case "visas":
            let where_ = v["country"] ?? ""
            let n = v["nights"] ?? ""
            return n.isEmpty ? "\(where_)." : "\(where_), \(n) nights."
        default:
            return t.title + "."
        }
    }

    /// Hand the finished set to whoever can act on it. The flow gathers;
    /// the screen executes. Keeping those apart is what stops the
    /// conversation layer from quietly becoming the app.
    func deliver(tool: ChappyTool, values: [String: String]) {
        var info: [String: Any] = ["tool": tool.id]
        for (k, val) in values { info[k] = val }
        NotificationCenter.default.post(name: .chappyFlowResult, object: nil, userInfo: info)
        if let screen = tool.screen {
            NotificationCenter.default.post(name: screen, object: nil, userInfo: info)
        }
    }
}

// =====================================================================
// MARK: - CHAPPY RESULT (Build 198) — ONE SHAPE FOR EVERY ANSWER
// =====================================================================
//
// Blueprint §11: every agent returns a predictable structured result,
// and the assistant summarises, compares and recommends rather than
// dumping raw output.
//
// The important line in that section is the last one — always clearly
// distinguish facts from recommendations. Chappy's travel reports have
// done that from the start (findings in one colour, the verdict in
// another, "we think" never dressed as "it is"). This brings the same
// discipline to everything spoken.
//
struct ChappyResult {

    struct Option {
        let title: String
        let subtitle: String
        /// 0-100. Comparable ONLY within one result set.
        let score: Int
        /// Why this one, in the wearer's terms. Never a number on its own.
        let why: String
        // BUILD 203: the raw facts the ranking used, kept so it can
        // explain itself. A recommendation that cannot say why it beat
        // the obvious answer is asking to be trusted rather than
        // believed, and the obvious answer here is always the biggest
        // number of stars.
        var stars: Double = 0
        var reviews: Int = 0
        var open: Bool?
        var metres: Double?
    }

    let toolID: String
    let ok: Bool
    /// One sentence, spoken. This is the whole answer for someone with
    /// the phone in a pocket.
    let headline: String
    /// The longer version, for the screen.
    let detail: String
    /// Ranked best-first. Empty is fine and means "nothing to choose".
    let options: [Option]
    let error: String?

    static func failed(_ toolID: String, _ why: String) -> ChappyResult {
        ChappyResult(toolID: toolID, ok: false,
                     headline: why, detail: "", options: [], error: why)
    }

    /// BUILD 203 — WHY THE OBVIOUS ANSWER LOST.
    ///
    /// If something in the list has visibly more stars than the winner,
    /// the wearer will notice on screen and conclude the ranking is
    /// broken. It is not — it is weighting evidence, opening hours and
    /// distance — but silence is indistinguishable from a bug.
    ///
    /// One clause, only when there IS a higher-rated option, and only
    /// naming the fact that actually decided it.
    static func defence(_ options: [Option]) -> String {
        guard let winner = options.first, options.count > 1 else { return "" }
        let better = options.dropFirst().max(by: { $0.stars < $1.stars })
        guard let b = better, b.stars > winner.stars + 0.15 else { return "" }
        let rounded = String(format: "%.1f", b.stars)
        if b.open == false {
            return " The \(rounded) is closed."
        }
        if b.reviews > 0, b.reviews < 60, winner.reviews >= b.reviews * 3 {
            return " The \(rounded) only has \(b.reviews) reviews."
        }
        if let bm = b.metres, let wm = winner.metres, bm > wm * 2.5, bm > 900 {
            return " The \(rounded) is \(String(format: "%.1f", bm / 1000)) km away."
        }
        if b.reviews > 0, b.reviews < 60 {
            return " The \(rounded) only has \(b.reviews) reviews."
        }
        return ""
    }

    /// What gets said out loud. Best option, why, and how many others —
    /// never a list read aloud, because nobody can hold six flights in
    /// their head at a bus stop.
    var spoken: String {
        guard ok else { return headline }
        guard let best = options.first else { return headline }
        var line = "\(headline) \(best.title) — \(best.why)."
        if options.count > 1 {
            line += " \(options.count - 1) other\(options.count == 2 ? "" : "s") on screen."
        }
        return line
    }
}

extension ChappyResult {

    // =================================================================
    // BUILD 200 — THE CONTRACT STOPS BEING DECORATION.
    //
    // §11 was declared in 198 and filled in by nothing, so Chappy
    // gathered five answers beautifully and then said "running it".
    // This is the first tool that actually returns the shape, and it
    // is the right one to start with: places is what gets asked for
    // most, and it is the only source in the app carrying two
    // independent ratings, a review count, a price level and an
    // opening state.
    //
    // The ranking rule, and the reason for it: a 5.0 from eleven
    // reviews is not better than a 4.6 from nine hundred. Rating alone
    // ranks noise to the top, which is exactly how every "best of"
    // list on the internet goes wrong. So the rating is weighted by
    // how much evidence sits behind it, and the weight saturates —
    // past a few hundred reviews more reviews stop telling you
    // anything new.
    //
    // §11's last line is the one that matters most: always clearly
    // distinguish facts from recommendations. Every `why` below is
    // made only of things that are true — a number, a distance, an
    // opening time. The recommendation is the ORDER, and the order is
    // ours to defend.
    // =================================================================
    static func from(_ spots: [ChappyPlaces.Spot],
                     kind: ChappyPlaces.Kind,
                     near lat: Double, lon: Double,
                     asked: String) -> ChappyResult {

        guard !spots.isEmpty else {
            return ChappyResult(toolID: "places", ok: false,
                                headline: "Nothing came back for \(asked) around here.",
                                detail: "", options: [], error: "empty")
        }

        func metres(_ s: ChappyPlaces.Spot) -> Double? {
            guard lat != 0 || lon != 0, s.lat != 0 || s.lon != 0 else { return nil }
            return ChappyPorts.km(lat, lon, s.lat, s.lon) * 1000
        }

        func distanceLine(_ m: Double) -> String {
            m < 950 ? "\(Int((m / 50).rounded()) * 50) metres"
                    : String(format: "%.1f km", m / 1000)
        }

        var options: [Option] = []
        for sp in spots {
            // Evidence-weighted rating. Both sources count; the one with
            // more reviews behind it counts for more.
            var weighted = 0.0, weight = 0.0
            if let r = sp.rating {
                let w = min(Double(sp.reviews ?? 0), 400) / 400
                weighted += r * (0.35 + 0.65 * w); weight += (0.35 + 0.65 * w)
            }
            if let g = sp.googleRating {
                let w = min(Double(sp.googleCount ?? 0), 400) / 400
                weighted += g * (0.35 + 0.65 * w); weight += (0.35 + 0.65 * w)
            }
            guard weight > 0 else { continue }
            let stars = weighted / weight
            var score = (stars / 5.0) * 100

            // Being open beats being marginally better rated. You are
            // standing outside it.
            if sp.openNow == true { score += 6 }
            if sp.openNow == false { score -= 22 }

            // Distance is a real cost on foot in the heat. Gentle, so it
            // never buries a much better place two streets further on.
            var whyBits: [String] = []
            let count = max(sp.reviews ?? 0, sp.googleCount ?? 0)
            whyBits.append(count > 0
                ? String(format: "%.1f from %d reviews", stars, count)
                : String(format: "%.1f", stars))
            if let m = metres(sp) {
                score -= min(m / 1000, 3.0) * 4
                whyBits.append(distanceLine(m))
            }
            if sp.openNow == true { whyBits.append("open now") }
            if sp.openNow == false { whyBits.append("closed") }
            if !sp.priceLevel.isEmpty { whyBits.append(sp.priceLevel) }
            // The disagreement between the two sources is the most useful
            // sentence in the whole app and it costs nothing to say.
            if let note = sp.divergenceNote { whyBits.append(note) }

            options.append(Option(title: sp.name,
                                  subtitle: sp.address,
                                  score: Int(score.rounded()),
                                  why: whyBits.joined(separator: ", "),
                                  stars: stars,
                                  reviews: count,
                                  open: sp.openNow,
                                  metres: metres(sp)))
        }

        options.sort { $0.score > $1.score }
        guard !options.isEmpty else {
            return ChappyResult(toolID: "places", ok: false,
                                headline: "Found some places, but none of them are rated.",
                                detail: "", options: [], error: "unrated")
        }
        return ChappyResult(toolID: "places", ok: true,
                            headline: "\(kind.label).\(Self.defence(options))",
                            detail: options.map { "\($0.title) — \($0.why)" }
                                           .joined(separator: "\n"),
                            options: options, error: nil)
    }
}

// =====================================================================
// MARK: - WHAT IT JUST SAID (Build 202)
// =====================================================================
//
// "The second one." "That one." "Take me there." "How far is it?"
//
// Every assistant worth comparing to resolves a reference to what it
// just told you, and Chappy could not — so the fifteen-workflow run
// ended with him repeating a warung's name back to the app that had
// just named it. That is the moment a conversation stops being one.
//
// Deliberately small and deliberately short-lived: the last result
// set, for two minutes. A reference to something said an hour ago is
// not a reference, it is a guess.
//
final class ChappyLastResult {

    static let shared = ChappyLastResult()
    private init() {}

    private(set) var result: ChappyResult?
    private var at = Date.distantPast
    private static let lifetime: TimeInterval = 120

    var isFresh: Bool {
        result != nil && Date().timeIntervalSince(at) < Self.lifetime
    }

    func remember(_ r: ChappyResult) {
        guard r.ok, !r.options.isEmpty else { return }
        result = r
        at = Date()
    }

    func clear() { result = nil; at = .distantPast }

    private static let ordinals: [(String, Int)] = [
        ("first", 0), ("1st", 0), ("one", 0),
        ("second", 1), ("2nd", 1), ("two", 1),
        ("third", 2), ("3rd", 2), ("three", 2),
        ("fourth", 3), ("4th", 3), ("fifth", 4), ("5th", 4),
        ("last", -1),
    ]

    /// The option he means, or nil. "That one" and "it" mean the one
    /// that was named out loud, which is always the first.
    func referenced(_ c: String) -> ChappyResult.Option? {
        guard isFresh, let r = result else { return nil }
        for (word, index) in Self.ordinals where c.contains(word) {
            let i = index < 0 ? r.options.count - 1 : index
            guard i >= 0, i < r.options.count else { return nil }
            return r.options[i]
        }
        if c.contains("that one") || c.contains("that place") || c.contains(" it")
            || c.hasSuffix(" there") || c.contains("the one you said") {
            return r.options.first
        }
        return nil
    }

    /// Does this sentence read as a reference at all? Kept separate so a
    /// sentence that merely CONTAINS "it" doesn't hijack the router.
    /// AUDIT (202): the first cut treated every reference as a request to
    /// GO there, so "tell me about it" started navigating. Wanting to know
    /// about a place and wanting to stand in it are different sentences.
    enum Want { case go, describe }

    static func want(_ c: String) -> Want? {
        let goVerbs = ["take me", "navigate", "go there", "walk me", "ride me",
                       "drive me", "directions", "get me to"]
        let askVerbs = ["how far", "tell me about", "what about", "which one",
                        "what's it like", "whats it like", "is it open", "how good"]
        let nouns = ["one", "that", "there", "it"]
        guard nouns.contains(where: { c.contains($0) }) else { return nil }
        if askVerbs.contains(where: { c.contains($0) }) { return .describe }
        if goVerbs.contains(where: { c.contains($0) }) { return .go }
        return nil
    }

    static func looksLikeReference(_ c: String) -> Bool { want(c) != nil }
}

// =====================================================================
// MARK: - THE ROUTER LOG (Build 198) — §17
// =====================================================================
//
// "Log intent, selected tool, inputs, confidence, result and errors for
// debugging, subject to privacy requirements."
//
// In memory only, capped, never written to disk and never sent
// anywhere. The privacy requirement here is not a footnote: this
// buffer sees everything said to Chappy, so it lives and dies with the
// process and holds a hundred lines at most.
//
final class ChappyRouterLog {

    static let shared = ChappyRouterLog()
    private init() { load() }

    /// BUILD 221 — Codable, because this record was worth keeping and
    /// wasn't kept.
    ///
    /// Every field here is the answer to "why did Chappy do that": what
    /// it heard, which tier claimed the sentence, which tool ran, how
    /// confident it was, what came of it, and how long it really took.
    /// All of it lived in RAM behind a 100-entry cap and died on every
    /// app exit — so the one question it exists to answer could only be
    /// asked before you closed the app, which is never when you want to
    /// ask it.
    struct Entry: Codable {
        let at: Date
        let heard: String
        // BUILD 253: the list was six tiers out of date, and one of the
        // six it named — pocket — has no producer at all. Written out
        // properly because the
        // Settings screen colours off these strings, and a tier missing
        // from the list renders grey and reads as "nothing special".
        //   answer     — a module answered outright (flights, bags, fares)
        //   reference  — "that one", "there" resolved to a saved place
        //   tiles      — matched a screen by name
        //   flow       — a multi-step tool took it
        //   intent     — the eleven-action classifier took it
        //   plan       — the orchestrator ran a plan, one entry per step
        //   ask        — nothing matched; answered as a general question
        //   model      — handed to the session, which has tools
        //   untagged   — no tier recorded a decision; the LOG has a gap,
        //                which is not the same claim as "it failed"
        //   net        — a background network result, not a routing decision
        //   pocket     — declared since build 198, never once written
        let tier: String
        let tool: String?
        let confidence: Double?
        let outcome: String
        let ms: Int
    }

    private var store: [Entry] = []
    /// BUILD 253 — a lock, because this array is genuinely written from
    /// two threads and always has been.
    ///
    /// `add` is called from the router on the main actor, and also from
    /// ChappyFareSource.month, which is a nonisolated async method whose
    /// continuation resumes on the concurrent executor. So a background
    /// fare failure could append while the Settings screen was reading —
    /// undefined behaviour, and the kind that shows up as a crash nobody
    /// can reproduce. It was survivable while the screen read the array
    /// once on appear; 253 makes it read every two seconds, which is
    /// exactly the wrong direction to leave it.
    private let lock = NSLock()

    /// A copy, taken under the lock. Callers get a snapshot they own.
    var entries: [Entry] {
        lock.lock(); defer { lock.unlock() }
        return store
    }
    /// BUILD 221: 100 in memory was a display cap. On disk it can afford
    /// to be a real history without being a burden — a few hundred
    /// kilobytes for weeks of decisions.
    ///
    /// BUILD 262: 600 -> 1200. The shadow router writes a second row for
    /// every routed sentence, so at 600 the history this build depends on
    /// reading back would have quietly halved during the one build whose
    /// entire purpose is reading it back. Doubling the cap keeps the reach
    /// the same and costs a few hundred kilobytes.
    private static let cap = 1200

    private static let file = "chappy_routerlog.json"

    private var url: URL? {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)
            .first?.appendingPathComponent(Self.file)
    }

    /// Written on a background queue and coalesced — the router logs on
    /// every routed sentence and must never wait on a disk write.
    private let io = DispatchQueue(label: "chappy.routerlog.io", qos: .utility)
    private var saveWork: DispatchWorkItem?

    private func load() {
        guard let url, let d = try? Data(contentsOf: url),
              let rows = try? JSONDecoder().decode([Entry].self, from: d)
        else { return }
        // BUILD 245: was `entries = rows.suffix(Self.cap)`. suffix() returns
        // an ArraySlice and there is no implicit conversion to [Entry], so
        // this line does not compile as it stands in the repo. Found while
        // sweeping for the same mistake in the new log code.
        //
        // Worth knowing WHY it survived: it means the copy on GitHub is not
        // the copy that built 243. Since delivery here is `git reset --hard
        // origin/main`, a stale-but-broken file on the remote lands on the
        // Mac at pull time and fails the archive — with an error in a file
        // nobody touched this build, which is the worst kind to debug.
        lock.lock()
        store = Array(rows.suffix(Self.cap))
        lock.unlock()
    }

    private func scheduleSave() {
        // BUILD 253: under the same lock as the array. The lock was added
        // because `add` is reachable off the main thread from the fare
        // fetch; leaving this work item unsynchronised beside it would
        // have fixed the array and left the DispatchWorkItem next to it
        // racing — two concurrent adds can over-release it. Half a fix
        // to a data race reads like a whole one, which is worse than none.
        lock.lock(); defer { lock.unlock() }
        saveWork?.cancel()
        let snapshot = store
        let work = DispatchWorkItem { [weak self] in
            guard let self, let url = self.url,
                  let d = try? JSONEncoder().encode(snapshot) else { return }
            try? d.write(to: url, options: .atomic)
        }
        saveWork = work
        io.asyncAfter(deadline: .now() + 2.0, execute: work)
    }

    /// Everything Chappy decided, newest first, as plain readable lines.
    ///
    /// BUILD 253: sorted by time rather than reversed by append order,
    /// because a gap entry is written eight seconds late while carrying
    /// its decision's own timestamp. Worth knowing that NOTHING CALLS
    /// THIS — the export he actually uses is the Copy button on the "What
    /// Chappy did" screen, which builds its own string. Kept and corrected
    /// rather than deleted only because it is one line either way.
    func readableHistory(limit: Int = 200) -> String {
        let f = DateFormatter(); f.dateFormat = "d MMM HH:mm:ss"
        return entries.sorted { $0.at > $1.at }.prefix(limit).map { e in
            let c = e.confidence.map { String(format: " %.2f", $0) } ?? ""
            let t = e.tool.map { " → \($0)" } ?? ""
            return "\(f.string(from: e.at))  [\(e.tier)\(c)]  \"\(e.heard)\"\(t)  \(e.outcome)  \(e.ms)ms"
        }.joined(separator: "\n")
    }

    /// BUILD 253 — when a ROUTING DECISION was last recorded.
    ///
    /// The backstop compares this against the moment the sentence started
    /// routing. A timestamp rather than the boolean latch the first cut of
    /// 253 used, because a latch never cleared: once any tier had logged,
    /// the backstop stayed off for good.
    ///
    /// IT IS STILL GLOBAL, AND THAT IS A REAL LIMIT, SO IT IS WRITTEN
    /// DOWN RATHER THAN GLOSSED. If he barges in over a tier that is
    /// mid-await, the cancelled tier's continuation still runs and still
    /// logs — stamping this clock after the NEW sentence started, so the
    /// new sentence looks accounted for and gets no gap line. Closing
    /// that needs the route token carried into every one of the router's
    /// twenty-odd log calls, which is a bigger change than this build
    /// should make on top of everything else in it. The failure is a
    /// missing line rather than a wrong one, which is the right way for
    /// it to fail.
    ///
    /// `routeDecision: false` is for callers that are not deciding about
    /// a spoken sentence at all — the fare matrix logging an HTTP failure
    /// from a background thread, a Siri shortcut. Those get their entry
    /// but must not speak for whatever the router is holding.
    nonisolated(unsafe) static var lastDecisionAt = Date.distantPast

    func add(heard: String, tier: String, tool: String? = nil,
             confidence: Double? = nil, outcome: String, ms: Int,
             routeDecision: Bool = true, at: Date = Date()) {
        if routeDecision { Self.lastDecisionAt = Date() }
        lock.lock()
        store.append(Entry(at: at, heard: heard, tier: tier, tool: tool,
                           confidence: confidence, outcome: outcome, ms: ms))
        if store.count > Self.cap { store.removeFirst(store.count - Self.cap) }
        lock.unlock()
        // BUILD 221: coalesced two seconds out, so a run of commands
        // costs one write rather than one per sentence, and the router
        // never waits on the disk.
        scheduleSave()
        let c = confidence.map { String(format: " %.2f", $0) } ?? ""
        print("🧭 [Route] \(ms)ms \(tier)\(c) \(tool ?? "-") — \(outcome)")
    }

    /// Spoken answer to "what did you just do" — the debugging tool that
    /// works when the phone is in a pocket.
    func lastLine() -> String {
        guard let e = entries.last else { return "Nothing yet." }
        return "\(e.tier) handled it in \(e.ms) milliseconds: \(e.outcome)."
    }
}

// =====================================================================
// MARK: - THE ORCHESTRATOR (Build 198) — §5, §8, §16
// =====================================================================
//
// One model call that reads the registry rather than a hand-written
// prompt, returns one or more steps with a confidence for each, and
// never invents a slot value.
//
// The registry is generated into the prompt at call time. That is the
// entire reason the registry exists: adding a tool must not mean
// remembering to edit a prompt somewhere else. If those two ever
// disagree the assistant lies about what it can do, and that is a
// worse failure than not understanding.
//
// =====================================================================
// MARK: - BUILD 262 — THE SHADOW. STAGE ONE OF INVERTING THE ROUTER.
// =====================================================================
//
// THE PROBLEM, IN HIS WORDS: "I should be able to say any sentence to
// Chappy and it should know what the fuck I'm talking about." He is right,
// and the reason it doesn't is architectural, not a run of bugs.
//
// route() is 2,900 lines and roughly 780 `c.contains(...)` tests. The model
// is reached only when EVERY ONE of them has missed. So the ceiling on how
// well Chappy understands him is how well I guessed his phrasing in
// advance — and when I guess wrong he does not get "I didn't understand",
// he gets whichever branch happened to match a fragment. That is the
// "random shit" he describes, and it is the same defect every time:
//
//   "cheapest flight in October"  ->  the month-price search has existed
//                                     since 217; the trigger list had
//                                     "cheapest day" and not "cheapest
//                                     flight", so it opened a form and
//                                     asked him the question he was asking.
//
// THE PLAN IS TO INVERT IT: a model that reads the sentence decides, and
// the keyword ladder becomes a fast path for the twenty commands that must
// be instant and free, plus a fallback when the model is slow or down.
//
// THIS FILE IS STAGE ONE, AND IT CANNOT BREAK ANYTHING BY CONSTRUCTION.
// The ladder still decides everything. In parallel, the resolver is asked
// what it WOULD have done, and the answer is written to the router log and
// nowhere else. It never speaks, never acts, never touches memory, and its
// failures are silent. What it produces is evidence: every sentence he says
// for a day, with the ladder's answer and the model's answer side by side.
//
// Nothing gets promoted in stage two that has not been proven here.
//
// AND IT REUSES WHAT IS ALREADY THERE. ChappyOrchestrator.plan already
// renders the registry into a prompt, asks Gemini Flash, and returns tool
// steps with confidences. It has been called for years — but only after the
// ladder has failed all the way through, which is why it shows up in his
// log at three and a half seconds looking like the slow option. It is not
// slow because it is a model; it is late because it runs last.
enum ChappyShadow {

    /// Default ON for stage one. A switch because this costs real money on
    /// every sentence, and the moment the evidence is in it should go off.
    static var enabled: Bool {
        UserDefaults.standard.object(forKey: "chappy_shadow") as? Bool ?? true
    }

    /// Flash is cheap, but "cheap times every sentence for a week" is how a
    /// bill surprises someone. Hard stop, per day, and it says so when it
    /// trips rather than going quiet.
    private static let dailyCap = 300
    private static var todayKey: String {
        let f = DateFormatter(); f.dateFormat = "yyyy-MM-dd"
        f.locale = Locale(identifier: "en_US_POSIX")
        return "chappy_shadow_" + f.string(from: Date())
    }

    nonisolated(unsafe) private static var lastSeen = ""
    /// BUILD 262, AFTER REVIEW. The first cut remembered the last sentence
    /// FOREVER, so saying the same thing twice — which is exactly what a man
    /// does when the ladder mis-routed it the first time — was silently
    /// dropped. That repeat is the single most valuable row this build can
    /// collect, and I had written the one line that guarantees it never
    /// appears. Three seconds: long enough for a recogniser hiccup, far too
    /// short to swallow a deliberate second try.
    nonisolated(unsafe) private static var lastSeenAt = Date.distantPast
    private static let lock = NSLock()

    /// How many sentences have been shadowed today. On screen, because
    /// "it costs a fraction of a cent" is a claim and this is the number.
    ///
    /// Clamped, because the cap branch writes one extra to latch its log
    /// line and a settings row reading "301 of 300" is a bug report waiting
    /// to be filed.
    static var usedToday: Int { min(UserDefaults.standard.integer(forKey: todayKey), dailyCap) }
    static var capPerDay: Int { dailyCap }

    /// Fire and forget. Called from finish() on the whole sentence, before
    /// the compound splitter, so the model sees what he actually said rather
    /// than half of it.
    static func observe(_ raw: String, at: Date) {
        guard enabled else { return }
        // NO KEY, NO SHADOW, AND NO ROW. Review caught this: plan() returns
        // nil immediately when the Google key is missing, so without this
        // guard a key-less day would burn all three hundred slots writing
        // three hundred identical "the model had no answer" lines — and the
        // one screen this build exists to make readable would be full of
        // them.
        guard !(APIKeyManager.shared.getGoogleAPIKey() ?? "").isEmpty else { return }
        let c = raw.trimmingCharacters(in: CharacterSet(charactersIn: " ,.:;!?-")).lowercased()
        guard c.count > 3 else { return }

        // The recogniser delivers the same sentence more than once on a
        // partial-heavy utterance. One look per sentence.
        lock.lock()
        let repeated = (c == lastSeen && Date().timeIntervalSince(lastSeenAt) < 3)
        lastSeen = c
        lastSeenAt = Date()
        lock.unlock()
        guard !repeated else { return }

        let d = UserDefaults.standard
        let used = d.integer(forKey: todayKey)
        guard used < dailyCap else {
            if used == dailyCap {
                d.set(used + 1, forKey: todayKey)
                ChappyStandbyLog.note("👁️ [Shadow] Daily cap of \(dailyCap) reached — shadowing paused until tomorrow")
            }
            return
        }
        // THE COUNTER IS BUMPED AFTER THE REQUEST GOES OUT, NOT HERE.
        // Review's point, and it is the right one: this task sleeps five
        // seconds first, and a phone that gets pocketed and suspended in
        // that window never sends anything. Spending a slot for a request
        // that was never made makes the number on the settings screen a
        // lie in the one direction that matters — it would say he had used
        // his budget when he had not.

        // The row is stamped a millisecond BEFORE the sentence's own clock so
        // that on the "What Chappy did" screen — sorted newest first — the
        // mint row always lands directly UNDERNEATH the decision it is
        // commenting on. Review found the tie: build 253's untagged backstop
        // stamps its row with this same routeStartedAt value, Array.sort is
        // not documented as stable, and the one pairing this whole build
        // exists to show was the one that could come out in either order.
        let stamp = at.addingTimeInterval(-0.001)

        Task.detached(priority: .utility) {
            // WAIT FIVE SECONDS BEFORE ASKING, AND THIS IS NOT PADDING.
            //
            // A sentence that falls all the way through the ladder reaches
            // ChappyOrchestrator.plan itself, with a hard four-second ceiling
            // and a fall-through behind it. Firing the shadow's copy at the
            // same instant puts two requests to the same host in flight
            // together on the shared URLSession — and on a weak link that is
            // a plausible way to push the REAL one over its timeout and
            // change how a sentence routed. "It cannot affect the route"
            // has to be true, not nearly true.
            //
            // Nothing reads this result, so waiting costs exactly nothing.
            try? await Task.sleep(nanoseconds: 5_000_000_000)
            await MainActor.run {
                let ud = UserDefaults.standard
                ud.set(ud.integer(forKey: todayKey) + 1, forKey: todayKey)
            }
            // Stamped after the sleep: this number must measure the model,
            // not the delay in front of it.
            let began = Date()
            guard let plan = await ChappyOrchestrator.plan(c) else {
                await MainActor.run {
                    ChappyRouterLog.shared.add(
                        heard: c, tier: "shadow", tool: nil,
                        outcome: "the model had no answer — either no key, a timeout, or it declined",
                        ms: Int(Date().timeIntervalSince(began) * 1000),
                        routeDecision: false, at: stamp)
                }
                return
            }
            let ms = Int(Date().timeIntervalSince(began) * 1000)
            guard let first = plan.steps.first else {
                await MainActor.run {
                    ChappyRouterLog.shared.add(
                        heard: c, tier: "shadow", tool: "none",
                        outcome: "the model says no tool is needed — this is a question, not a command",
                        ms: ms, routeDecision: false, at: stamp)
                }
                return
            }
            // Every step, so a genuine two-part sentence is visible as one.
            let described = plan.steps.map { s -> String in
                let vals = s.values.isEmpty
                    ? ""
                    : " {" + s.values.map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ", ") + "}"
                return "\(s.toolID)\(vals)"
            }.joined(separator: " then ")

            await MainActor.run {
                ChappyRouterLog.shared.add(
                    heard: c, tier: "shadow", tool: first.toolID,
                    confidence: first.confidence,
                    outcome: "would run \(described)",
                    // ROUTE DECISION: FALSE, AND THIS MATTERS. Build 253's
                    // backstop uses lastDecisionAt to decide whether a
                    // sentence went unhandled. A shadow row claiming to be a
                    // decision would make every untagged sentence look
                    // accounted for, and the one diagnostic that has been
                    // telling the truth would start lying.
                    ms: ms, routeDecision: false, at: stamp)
            }
        }
    }
}

enum ChappyOrchestrator {

    struct Step {
        let toolID: String
        var values: [String: String]
        let confidence: Double
    }

    struct Plan {
        var steps: [Step]
        /// What Chappy says before a multi-step plan runs. §8: keep the
        /// user informed when a task has stages.
        var preamble: String?
    }

    /// §16, verbatim: high executes, medium clarifies, low asks.
    enum Band { case execute, clarify, ask }
    static func band(_ c: Double) -> Band {
        if c >= 0.80 { return .execute }
        if c >= 0.50 { return .clarify }
        return .ask
    }

    /// The tool contracts, rendered for the model. Derived, never typed
    /// twice.
    private static var contracts: String {
        ChappyRegistry.tools.map { t in
            let slots = t.slots.map { s -> String in
                let kind: String
                switch s.kind {
                case .airport:  kind = "city or airport name"
                case .place:    kind = "place name"
                case .date:     kind = "yyyy-MM-dd, only if a specific day was said"
                case .count:    kind = "whole number of people"
                case .nights:   kind = "whole number of nights"
                case .money:    kind = "whole number"
                case .yesNo:    kind = "yes or no"
                case .language: kind = "language name"
                case .text:     kind = "plain words"
                case .mode:     kind = "walk, drive, scooter or grab"
                case .priceBand:kind = "cheap, mid or nice"
                case .span:     kind = "month, 3 months, year or all time"
                }
                return "\(s.id) (\(kind))\(s.optional ? " [optional]" : "")"
            }.joined(separator: ", ")
            return "- \(t.id): \(t.title). slots: \(slots)"
        }.joined(separator: "\n")
    }

    static func plan(_ utterance: String) async -> Plan? {
        let key = APIKeyManager.shared.getGoogleAPIKey() ?? ""
        guard !key.isEmpty, utterance.count > 3,
              let url = URL(string: "https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=\(key)")
        else { return nil }

        let system = """
        You are the router for a wearable assistant called Chappy, worn by an Australian traveller in Asia.
        Decide which of these tools the request needs. A request may need more than one, in order.

        TOOLS
        \(contracts)

        Reply with ONLY this JSON:
        {"steps":[{"tool":"...","values":{"slot":"value"},"confidence":0.0}],"preamble":"..."}

        Rules:
        - Only include a slot you were actually told. NEVER invent a destination, a date, a number of people or a budget.
        - Omit a slot rather than guess it. Something else will ask for it.
        - confidence is your own honest estimate that this tool is what was meant, 0 to 1.
        - If the request needs nothing from this list, return {"steps":[]}.
        - preamble is one short sentence, only when there is more than one step. Otherwise "".
        - Do not answer the question. You are choosing tools, not replying.
        """
        let body: [String: Any] = [
            "systemInstruction": ["parts": [["text": system]]],
            "contents": [["role": "user", "parts": [["text": utterance]]]],
            "generationConfig": [
                "temperature": 0,
                "maxOutputTokens": 700,
                "responseMimeType": "application/json",
            ],
        ]
        var req = URLRequest(url: url)
        req.httpMethod = "POST"
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        // Same ceiling as the old classifier. A router that makes you wait
        // is worse than one that gives up — there is always a tier behind.
        req.timeoutInterval = 4
        req.httpBody = try? JSONSerialization.data(withJSONObject: body)

        guard let (data, resp) = try? await URLSession.shared.data(for: req),
              (resp as? HTTPURLResponse)?.statusCode == 200,
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let cands = json["candidates"] as? [[String: Any]],
              let content = cands.first?["content"] as? [String: Any],
              let parts = content["parts"] as? [[String: Any]],
              let text = parts.first?["text"] as? String,
              let d = text.data(using: .utf8),
              let obj = try? JSONSerialization.jsonObject(with: d) as? [String: Any],
              let rawSteps = obj["steps"] as? [[String: Any]]
        else { return nil }

        var steps: [Step] = []
        for r in rawSteps {
            guard let id = r["tool"] as? String, ChappyRegistry.tool(id: id) != nil else { continue }
            var vals: [String: String] = [:]
            if let v = r["values"] as? [String: Any] {
                for (k, any) in v {
                    if let sv = any as? String, !sv.isEmpty, sv.lowercased() != "null" { vals[k] = sv }
                    if let iv = any as? Int { vals[k] = String(iv) }
                }
            }
            let conf = (r["confidence"] as? Double) ?? 0.6
            steps.append(Step(toolID: id, values: vals, confidence: conf))
        }
        guard !steps.isEmpty else { return Plan(steps: [], preamble: nil) }
        let pre = (obj["preamble"] as? String)?.trimmingCharacters(in: .whitespacesAndNewlines)
        return Plan(steps: steps, preamble: (pre?.isEmpty ?? true) ? nil : pre)
    }

    /// §8: pass what one step learned into the next. Deliberately narrow —
    /// only the entities that genuinely mean the same thing everywhere.
    /// "to" on a flight and "country" on a visa are the same place; "when"
    /// and "nights" travel with it. Everything else stays where it was,
    /// because a shared bag of loose values is how one wrong answer
    /// contaminates a whole plan.
    static func carry(_ from: [String: String], into next: inout [String: String]) {
        let place = from["to"] ?? from["country"] ?? from["where"]
        for key in ["to", "country", "where"] where next[key] == nil {
            // AUDIT (200): `if let place,` is Swift 5.7 shorthand. It compiles
            // on every Xcode this project has seen, and writing it out costs
            // nothing — which is the correct trade on a file that has already
            // cost two archive cycles.
            if let placeValue = place,
               ChappyRegistry.tools.contains(where: { $0.slots.contains { $0.id == key } }) {
                next[key] = placeValue
            }
        }
        for key in ["when", "nights", "party"] where next[key] == nil {
            if let v = from[key] { next[key] = v }
        }
    }
}

// =====================================================================
// MARK: - WHAT NEXT (Build 198) — §9
// =====================================================================
//
// "Suggestions must be relevant, concise and optional — never spam."
//
// So: one suggestion, only after something actually completed, only
// when it follows obviously from what was just done, and never twice
// for the same thing in a row. A suggestion you have already declined
// is not a suggestion, it is nagging.
//
enum ChappyNext {

    // BUILD 206 — A SUGGESTION THAT KNOWS SOMETHING.
    //
    // 198's version was one hardcoded line per tool, offered whenever
    // that tool finished. The blueprint asks for relevance and for
    // suggestions to be genuinely optional, and a line that fires
    // regardless of the hour, the country or whether you have already
    // said no twice is neither.
    //
    // Four gates, in order of how cheap they are to check:
    //
    //   1. Have you turned two of these down in a row? Then stop. Two
    //      refusals is a preference, not a coincidence, and it lasts
    //      the rest of the day.
    //   2. Have I offered this exact thing already? Then don't repeat.
    //   3. Does it follow from what just happened AND from where and
    //      when you are? A fuel stop at 3am is not a suggestion.
    //   4. Is there actually something useful to say? Silence is a
    //      perfectly good answer and it is the default.

    private static var lastOffered: String?
    private static var declines = 0
    private static var declinedOn: Date?

    /// Called when he says no, or simply moves on to something else.
    static func declined() {
        declines += 1
        declinedOn = Date()
    }

    /// Called when he takes one up — the count resets, because a person
    /// who accepts is a person who wants them.
    static func accepted() {
        declines = 0
        declinedOn = nil
    }

    private static var muted: Bool {
        guard declines >= 2, let d = declinedOn else { return false }
        // Until tomorrow, then try again. A permanent mute from two
        // shrugs is its own kind of wrong.
        return Calendar.current.isDateInToday(d)
    }

    private static var hour: Int { Calendar.current.component(.hour, from: Date()) }

    /// Abroad changes what is worth mentioning. A visa suggestion at
    /// home is admin; the same line in Denpasar is the reason you are
    /// carrying the thing.
    private static var abroad: Bool {
        let code = ContextEngine.shared.snapshot.countryCode?.uppercased()
        guard let code, !code.isEmpty else { return false }
        return code != "AU"
    }

    static func after(_ toolID: String, values: [String: String]) -> String? {
        guard !muted else { return nil }
        // BUILD 215 — §16's switch, and §14's feedback.
        guard !ChappyForesight.isMuted, ChappyForesight.mode != .passive else { return nil }
        // Declined twice and never taken up is an answer. Stop asking.
        guard !ChappyLedger.shared.isUnwanted(toolID) else { return nil }

        let suggestion: String?
        switch toolID {

        case "flights":
            // The visa is the thing that stops you boarding. Say it
            // first, and only when we know where he is going.
            if let to = values["to"], let country = ChappyPorts.byIATA(to)?.country,
               !country.isEmpty {
                suggestion = "Want me to check what \(country) wants for a visa?"
            } else if values["oneway"] == "yes" {
                // One-way is his default, and an onward ticket is what
                // gets asked for at the counter.
                suggestion = "Want the onward-ticket rule for that one?"
            } else {
                suggestion = "Want me to check the bags on that?"
            }

        case "travel":
            suggestion = values["when"] == nil
                ? "Want me to look at the weather for those months?"
                : "Want me to price the flights for those dates?"

        case "visas":
            suggestion = "Want the onward-ticket rule for that one?"

        case "navigate":
            // The blueprint's own navigation examples, gated on the hour
            // rather than offered blindly. Nobody wants a lunch
            // suggestion at four in the afternoon.
            if hour >= 11 && hour <= 14 { suggestion = "Want somewhere to eat near there?" }
            else if hour >= 18 && hour <= 21 { suggestion = "Want somewhere to eat near there?" }
            else if hour >= 22 || hour <= 5 { suggestion = nil }
            else { suggestion = nil }

        case "food", "attractions":
            // BUILD 212: the first suggestion that knows something about
            // him. If he is standing in a place he keeps coming back to,
            // saying so is more useful than offering directions to
            // somewhere he already knows the way to — and it says WHY,
            // which is the rule that stops this reading as surveillance.
            let snap = ContextEngine.shared.snapshot
            if let h = ChappyPatterns.here(lat: snap.latitude ?? 0, lon: snap.longitude ?? 0),
               h.strength == .habit {
                suggestion = "You've been here \(h.visits) times — want the usual sort of thing?"
            } else {
                suggestion = "Say take me there and I'll run it."
            }

        case "weather":
            // A forecast is a complete thought — except on a travel day
            // abroad, when it is half of one.
            suggestion = abroad && (hour >= 5 && hour <= 9)
                ? "Want what's on today?"
                : nil

        case "currency", "memory", "search", "atlas", "briefs", "upcoming",
             "dictate", "options", "translate", "reminders":
            suggestion = nil

        default:
            suggestion = nil
        }

        guard let sug = suggestion, sug != lastOffered else { return nil }
        lastOffered = sug
        ChappyLedger.shared.record(.suggested, subject: toolID, detail: sug)
        return sug
    }

    static func clear() { lastOffered = nil }
}

// =====================================================================
// MARK: - THE PERMISSION GATE (Build 198) — §10
// =====================================================================
//
// "The orchestrator should distinguish between find, suggest, prepare
// and execute. Never book, purchase or send something merely because
// the user mentioned it casually."
//
// An honest note about this one. Every tool in the registry today is
// .search — Chappy cannot spend your money, because there is no
// booking API left that a solo developer can reach: Amadeus is
// decommissioned, Airbnb's closed in 2019, the rest are partner-only.
// So this gate currently gates nothing.
//
// It is here anyway, and it is here NOW rather than later, because the
// moment a tool is added that deletes a trip file or sends a message,
// the gate has to already exist and already be the path everything
// travels down. A safety layer bolted on afterwards is one that gets
// bypassed by whatever was written before it.
//
enum ChappyGate {

    enum Verdict { case go, confirm(String) }

    static func check(_ tool: ChappyTool, values: [String: String]) -> Verdict {
        switch tool.permission {
        case .search:
            return .go
        case .act:
            return .confirm("\(ChappyFlow.summary(tool, values)) Shall I?")
        case .destructive:
            return .confirm("That will delete it and I can't undo it. Say yes to go ahead.")
        }
    }
}


// =====================================================================
// MARK: - CHAPPY SELF TEST (Build 207) — §17, §18
// =====================================================================
//
// "Make tools independently testable. Build automated tests for common
// phrases, ambiguous phrases, multi-intent requests and missing
// information."
//
// There is no test target in this project and adding one means editing
// the Xcode project file, which this week has demonstrated is a
// genuinely dangerous thing to do casually. So the tests live in the
// app and run on demand: "Chappy, self test".
//
// That is a real trade and worth naming. What this catches: every
// parser, matcher, ranking and confidence rule, against the exact
// phrasings that matter. What it CANNOT catch is what actually broke
// this week — a property declared in the wrong struct, a nested type's
// isolation, a stray character typed into a file. Those are compiler
// problems and only a compiler finds them.
//
// So this is not a substitute for a test target. It is the coverage
// that can exist today, and every check below is one I have otherwise
// been running by hand in a simulator beside the app, which proves
// nothing about the code that ships.
//
enum ChappySelfTest {

    struct Case {
        let name: String
        let ok: Bool
        let detail: String
    }

    static func run() -> [Case] {
        var out: [Case] = []

        func check(_ name: String, _ got: String?, _ want: String?) {
            let ok = got == want
            out.append(Case(name: name, ok: ok,
                            detail: ok ? (got ?? "nil")
                                       : "got \(got ?? "nil"), wanted \(want ?? "nil")"))
        }

        func checkTile(_ said: String, _ wantToolID: String?) {
            let got = ChappyTiles.match(said)
                .flatMap { ChappyRegistry.tool(forScreen: $0.note)?.id }
                ?? ChappyTiles.leading(said)
                    .flatMap { ChappyRegistry.tool(forScreen: $0.tile.note)?.id }
            check("route: \(said)", got, wantToolID)
        }

        // ---- common phrasings -------------------------------------
        checkTile("run flights", "flights")
        checkTile("hey chappy run flights", "flights")
        checkTile("i need flights", "flights")
        checkTile("open travel desk", "travel")
        checkTile("check the weather", "weather")
        checkTile("do visas", "visas")
        checkTile("give me currency", "currency")

        // ---- misspellings and mishearings -------------------------
        checkTile("transalte", "translate")
        checkTile("travle desk", "travel")

        // ---- phrases that must NOT be claimed ----------------------
        // Navigation owns these. A tile matcher that takes them is worse
        // than one that takes nothing.
        checkTile("take me to the beach", nil)
        checkTile("open maps", nil)
        checkTile("find a chemist", nil)

        // ---- a name with the details attached ----------------------
        checkTile("flights to bali on the seventh", "flights")
        checkTile("visa indonesia", "visas")

        // ---- dates: the ones that must resolve --------------------
        let sept7 = ChappySlots.parse("the seventh of september", as: .date)
        out.append(Case(name: "date: the seventh of september",
                        ok: sept7?.hasSuffix("-09-07") == true,
                        detail: sept7 ?? "nil"))
        check("date: tomorrow is not nil",
              ChappySlots.parse("tomorrow", as: .date) == nil ? nil : "ok", "ok")

        // ---- dates: the ones that must REFUSE ---------------------
        // This is the most important test in the file. A search built on
        // a guessed date is worse than another question.
        check("date refuses 'september'", ChappySlots.parse("september", as: .date), nil)
        check("date refuses 'next month'", ChappySlots.parse("next month", as: .date), nil)
        check("date refuses 'sometime soon'", ChappySlots.parse("sometime soon", as: .date), nil)

        // ---- airports, including the ones with no airport ----------
        // ---- BUILD 224: the outcome loop --------------------------
        //
        // The property that matters is the GATE, not the arithmetic: a
        // cold predictor must not be allowed to interrupt him. That is
        // the Google Now failure, and it is the one thing here that
        // cannot be allowed to regress quietly.
        let cold = ChappyOutcomes.Score(sort: .place, resolved: 0, hits: 0)
        check("outcomes: a cold predictor is not trusted",
              cold.trusted ? "yes" : "no", "no")
        let thin = ChappyOutcomes.Score(sort: .place, resolved: 4, hits: 4)
        check("outcomes: perfect but thin is still not trusted",
              thin.trusted ? "yes" : "no", "no")
        let good = ChappyOutcomes.Score(sort: .place, resolved: 8, hits: 6)
        check("outcomes: 6 of 8 earns the right to speak",
              good.trusted ? "yes" : "no", "yes")
        let bad = ChappyOutcomes.Score(sort: .place, resolved: 12, hits: 3)
        check("outcomes: 3 of 12 is disgraced",
              bad.disgraced ? "yes" : "no", "yes")
        check("outcomes: disgraced is never trusted",
              bad.trusted ? "yes" : "no", "no")
        check("outcomes: a settled score needs six",
              ChappyOutcomes.Score(sort: .place, resolved: 6, hits: 4).settled ? "yes" : "no", "yes")
        check("outcomes: every sort explains itself",
              ChappyOutcomes.Sort.allCases.allSatisfy { !$0.spoken.isEmpty } ? "yes" : "no", "yes")
        check("outcomes: off means silent",
              ChappyForesight.mode == .off ? (ChappyForesight.anticipate() == nil ? "silent" : "spoke")
                                           : "silent", "silent")

        // ---- BUILD 222: the semantic classifier -------------------
        //
        // Tested by walking the RULES rather than by trying phrases I
        // expect to work — the same discipline that caught a tool with
        // no trigger words in 199. Each of these is a rule boundary, and
        // the ordering ones matter most: a date that bites has to
        // outrank whatever it is a date about.
        func meaning(_ title: String, _ kind: ChappyMemory.Kind = .note) -> String {
            ChappyMemory.classify(kind: kind, title: title).rawValue
        }
        check("meaning: passport expiry is a deadline, not identity",
              meaning("my passport expires in March"), "temporal")
        check("meaning: passport alone is identity",
              meaning("my passport is Australian"), "identity")
        check("meaning: a spend is transactional",
              meaning("lunch", .spend), "transactional")
        check("meaning: a saved place is spatial",
              meaning("that warung", .place), "spatial")
        check("meaning: a verdict is affective",
              meaning("best fish soup I've had all week"), "affective")
        check("meaning: a standing avoidance is a preference",
              meaning("I avoid red meat"), "preference")
        check("meaning: a routine is procedural",
              meaning("the way I pack is shoes first"), "procedural")
        check("meaning: unfinished business is a project",
              meaning("still need to sort the onward ticket"), "project")
        check("meaning: a photo is the diary",
              meaning("sunset over the rice fields", .photo), "episodic")
        // The original phrase here was "the menu says no pork", which
        // returns .preference — because "no pork" is a dietary marker and
        // that rule fires before the kind check. That is arguably the
        // right answer and definitely the wrong TEST: it was asserting
        // the kind fallback while feeding it a phrase that never reaches
        // it. Caught by running the rules rather than reading them.
        check("meaning: a scan with no personal marker is a world fact",
              meaning("opening hours nine to five", .scan), "semantic")
        check("meaning: a dietary marker beats the kind fallback",
              meaning("the menu says no pork", .scan), "preference")
        check("meaning: every type has a label and an icon",
              ChappyMemory.Semantic.allCases
                .allSatisfy { !$0.label.isEmpty && !$0.icon.isEmpty } ? "yes" : "no", "yes")
        check("meaning: identity outlasts episodic",
              ChappyMemory.Semantic.identity.durabilityDays
                > ChappyMemory.Semantic.episodic.durabilityDays ? "yes" : "no", "yes")
        check("meaning: identity outweighs episodic",
              ChappyMemory.Semantic.identity.baseWeight
                > ChappyMemory.Semantic.episodic.baseWeight ? "yes" : "no", "yes")
        check("meaning: eleven types, no more no less",
              String(ChappyMemory.Semantic.allCases.count), "11")

        // ---- BUILD 217: the flight desk ---------------------------
        //
        // Added because 199 shipped a `navigate` tool with no trigger
        // words for two builds and nothing noticed. The lesson was to
        // test the TABLE rather than the phrases I expect to work, so
        // these walk the actual data.
        check("bags: jetstar known",
              ChappyBags.rule("jetstar")?.code, "JQ")
        check("bags: code lookup",
              ChappyBags.rule("GA")?.carrier, "Garuda Indonesia")
        check("bags: unknown airline is nil",
              ChappyBags.rule("wibble")?.code, nil)
        check("bags: every rule has a carrier and a code",
              ChappyBags.rules.allSatisfy { !$0.carrier.isEmpty && !$0.code.isEmpty }
                ? "yes" : "no", "yes")
        check("bags: universal rules present",
              ChappyBags.universal.isEmpty ? "empty" : "present", "present")
        check("routes: BNE-DPS has carriers",
              ChappyRoutes.legs("BNE", "DPS").isEmpty ? "none" : "some", "some")
        check("routes: reversed lookup works",
              ChappyRoutes.legs("DPS", "BNE").isEmpty ? "none" : "some", "some")
        check("routes: unknown route is empty",
              ChappyRoutes.legs("BNE", "ZZZ").isEmpty ? "none" : "some", "none")
        check("routes: every leg has a baggage rule",
              ChappyRoutes.table.values.flatMap { $0 }
                .allSatisfy { ChappyBags.rule($0.carrier) != nil } ? "yes" : "no", "yes")
        check("routes: hours read as words",
              ChappyRoutes.spokenHours(6.5), "6 and a half hours")
        check("routes: whole hours read plainly",
              ChappyRoutes.spokenHours(3.0), "3 hours")
        check("fares: journal decodes",
              ChappyFareJournal.all.count >= 0 ? "yes" : "no", "yes")
        check("fares: a verdict needs two readings",
              ChappyFareJournal.judge(500, origin: "ZZ1", dest: "ZZ2") == nil
                ? "nil" : "value", "nil")
        check("fares: source dormant without a token",
              ChappyFareSource.isConfigured
                ? "on" : (ChappyFareSource.token.isEmpty ? "off" : "on"),
              ChappyFareSource.token.isEmpty ? "off" : "on")
        check("fares: matrix parser survives rubbish",
              ChappyFareSource.parseMatrix(Data("not json".utf8),
                                           currency: "aud").isEmpty ? "empty" : "rows",
              "empty")
        check("fares: month key shape",
              ChappyFlightsPrefs.monthKey(fromISO: "2026-09-07"), "2026-09")
        check("fares: month key refuses rubbish",
              ChappyFlightsPrefs.monthKey(fromISO: "nope"), nil)
        check("fares: prefs never return empty",
              ChappyFlightsPrefs.origin.isEmpty ? "empty" : "set", "set")

        check("airport: brisbane", ChappySlots.parse("brisbane", as: .airport), "BNE")
        check("airport: bali", ChappySlots.parse("bali", as: .airport), "DPS")
        check("airport: ubud resolves to Denpasar",
              ChappySlots.parse("ubud", as: .airport), "DPS")
        check("airport: filler stripped",
              ChappySlots.parse("um, brisbane i think", as: .airport), "BNE")
        check("airport: window match",
              ChappySlots.parse("bali on the seventh", as: .airport), "DPS")
        check("airport refuses nonsense",
              ChappySlots.parse("narnia", as: .airport), nil)

        // ---- the other kinds --------------------------------------
        check("count: just the two of us", ChappySlots.parse("just the two of us", as: .count), "2")
        check("count: just me", ChappySlots.parse("just me", as: .count), "1")
        check("nights: about two months", ChappySlots.parse("about two months", as: .nights), "60")
        check("nights: six weeks", ChappySlots.parse("six weeks", as: .nights), "42")
        check("money: five grand", ChappySlots.parse("five grand", as: .money), "5000")
        check("yes: yeah same as usual", ChappySlots.parse("yeah, same as usual", as: .yesNo), "yes")
        check("no: nah", ChappySlots.parse("nah", as: .yesNo), "no")
        check("mode: motorbike is scooter", ChappySlots.parse("motorbike", as: .mode), "scooter")
        check("mode: gojek is grab", ChappySlots.parse("gojek", as: .mode), "grab")
        check("price: warung is cheap", ChappySlots.parse("warung food", as: .priceBand), "cheap")

        // ---- confidence bands -------------------------------------
        check("band 0.9 executes",
              String(describing: ChappyOrchestrator.band(0.9)), "execute")
        check("band 0.6 clarifies",
              String(describing: ChappyOrchestrator.band(0.6)), "clarify")
        check("band 0.2 asks",
              String(describing: ChappyOrchestrator.band(0.2)), "ask")

        // ---- ranking: the five-star trap --------------------------
        // Eleven reviews at 5.0 must not beat nine hundred at 4.6. This
        // is the rule every "best of" list on the internet gets wrong.
        let trap = [
            ChappyResult.Option(title: "Eleven Reviews", subtitle: "", score: 0, why: "",
                                stars: 5.0, reviews: 11, open: true, metres: 200),
            ChappyResult.Option(title: "Nine Hundred", subtitle: "", score: 0, why: "",
                                stars: 4.6, reviews: 912, open: true, metres: 400),
        ]
        let defended = ChappyResult.defence([trap[1], trap[0]])
        out.append(Case(name: "ranking explains a lost five-star",
                        ok: defended.contains("11 reviews"),
                        detail: defended.isEmpty ? "said nothing" : defended))

        // ---- the never-interviewed set ----------------------------
        for word in ["emergency", "stop", "cancel"] {
            out.append(Case(name: "never interviewed: \(word)",
                            ok: ChappyRegistry.neverInterviewed.contains(word),
                            detail: word))
        }

        // ---- BUILD 215: the ledger and the switch -------------------
        let modeOK = ChappyForesight.Mode.allCases.count == 4
        out.append(Case(name: "foresight: four modes exist", ok: modeOK,
                        detail: ChappyForesight.mode.rawValue))
        out.append(Case(name: "foresight: off means silent",
                        ok: ChappyForesight.mode != .off || ChappyForesight.anticipate() == nil,
                        detail: "global switch"))
        out.append(Case(name: "ledger: unwanted needs 2 declines and 0 accepts",
                        ok: !ChappyLedger.shared.isUnwanted("a-subject-never-seen"),
                        detail: "\(ChappyLedger.shared.entries.count) entries"))
        out.append(Case(name: "ledger: what-changed always answers",
                        ok: !ChappyLedger.shared.whatChanged().isEmpty,
                        detail: "spoken audit"))

        // ---- BUILD 212: the pattern engine's rules ------------------
        // A habit needs evidence. These assert the thresholds rather than
        // the data, because the data is his and a test cannot depend on
        // where he happened to go this week.
        let sample = ChappyPatterns.habits()
        out.append(Case(name: "patterns: nothing weak is called a habit",
                        ok: sample.allSatisfy { $0.strength != .habit || ($0.visits >= 5 && $0.days >= 3) },
                        detail: "\(sample.count) clusters"))
        out.append(Case(name: "patterns: confidence stays in range",
                        ok: sample.allSatisfy { $0.confidence >= 0 && $0.confidence <= 1 },
                        detail: sample.first.map { String(format: "top %.2f", $0.confidence) } ?? "none yet"))
        out.append(Case(name: "patterns: digest is wording, not a dump",
                        ok: ChappyPatterns.digest(lat: nil, lon: nil).count < 400,
                        detail: "digest length"))
        // Hoisted out of the argument: an immediately-invoked closure in
        // a call argument is what timed out the type checker in 191.
        let digestText = ChappyPatterns.digest(lat: nil, lon: nil)
        let flagged = digestText.isEmpty || digestText.contains("never confirmed by him")
        out.append(Case(name: "patterns: digest flags itself as observed",
                        ok: flagged, detail: "provenance wording"))

        // ---- AUDIT (208): every tool must be reachable BY NAME -----
        // navigate had no trigger words for two builds and nothing
        // noticed, because I kept testing phrases I expected to work
        // rather than checking coverage tool by tool. A test that
        // enumerates the registry cannot miss one.
        for tool in ChappyRegistry.tools {
            let reachable = ChappyTiles.all.contains { tile in
                ChappyRegistry.tool(forScreen: tile.note)?.id == tool.id
            }
            out.append(Case(name: "reachable by name: \(tool.id)",
                            ok: reachable,
                            detail: reachable ? "" : "no trigger words"))
        }

        // ---- registry integrity -----------------------------------
        let ids = Set(ChappyRegistry.tools.map { $0.id })
        out.append(Case(name: "registry: no duplicate tool ids",
                        ok: ids.count == ChappyRegistry.tools.count,
                        detail: "\(ChappyRegistry.tools.count) tools"))
        let overAsked = ChappyRegistry.tools.filter { $0.slots.filter { !$0.optional }.count > 3 }
        out.append(Case(name: "registry: nothing asks more than 3 questions",
                        ok: overAsked.isEmpty,
                        detail: overAsked.map { $0.id }.joined(separator: ", ")))

        return out
    }

    /// Spoken, because it gets run with the phone in a pocket.
    static func spokenSummary(_ cases: [Case]) -> String {
        let failed = cases.filter { !$0.ok }
        if failed.isEmpty { return "All \(cases.count) checks passed." }
        let names = failed.prefix(3).map { $0.name }.joined(separator: ", ")
        return "\(failed.count) of \(cases.count) failed: \(names)."
    }

    /// Printed, because the detail is what you actually fix from.
    static func printAll(_ cases: [Case]) {
        print("🧪 [SelfTest] \(cases.filter { $0.ok }.count)/\(cases.count) passed")
        for c in cases where !c.ok {
            print("   ❌ \(c.name) — \(c.detail)")
        }
    }
}


// =====================================================================
// MARK: - CHAPPY PATTERNS (Build 212) — THE THING THAT NOTICES
// =====================================================================
//
// Chappy has logged where he goes for ninety days and reasoned from
// none of it. The Atlas counts visits per stop to decide how big to
// draw a pin, and that was the entire behavioural awareness in the app.
//
// This is the pattern engine the spec asks for, and the reason it comes
// first is that §2, §3, §4 and §7 are all impossible without it —
// suggestive reasoning, prediction, adaptation and foresight every one
// need something that has already noticed.
//
// Three deliberate choices:
//
//   * PURE ARITHMETIC. No model, no network, no vector index. It reads
//     JSON the trail already writes and counts. It works on a bus in
//     Laos, which is where it has to work.
//
//   * READS FROM DISK, NOT FROM ChappyTrail. That class is @MainActor
//     and this runs in the router, which is not — the crossing that has
//     cost three archive cycles this week. It decodes the same files
//     into its own structs, exactly as ChappyProfileLite does. Nested
//     types inside an isolated class are an argument I am not having
//     again.
//
//   * A HABIT NEEDS EVIDENCE. Three visits before anything is called a
//     pattern, and confidence rises with observations and falls with
//     silence. One dinner is not a routine, and the fastest way to make
//     an assistant feel stupid is to tell someone they "always" do
//     something they did once.
//
enum ChappyPatterns {

    // ---------------------------------------------------------------- data
    /// Mirrors ChappyTrail's on-disk shape. Deliberately separate: see
    /// the isolation note above.
    private struct DiskVisit: Codable {
        var arrive: Date
        var depart: Date?
        var lat: Double
        var lon: Double
        var name: String?
    }
    private struct DiskDay: Codable {
        var visits: [DiskVisit]?
    }

    /// A place he keeps going back to, and what is true about when.
    struct Habit: Identifiable {
        var id: String { key }
        let key: String
        var name: String
        var lat: Double
        var lon: Double
        /// How many separate visits, across how many distinct days.
        var visits: Int
        var days: Int
        var firstSeen: Date
        var lastSeen: Date
        /// Hours of the day it happens, 0-23, most common first.
        var hours: [Int]
        /// Weekdays, 1 = Sunday, most common first.
        var weekdays: [Int]
        /// Typical time spent, in minutes. Nil when departures are unknown.
        var typicalMinutes: Int?

        /// 0-1. Evidence, recency and regularity — in that order of
        /// weight, because the spec is right that repeated observation
        /// matters more than anything else.
        var confidence: Double {
            let evidence = min(Double(visits), 12) / 12          // saturates
            let spread = min(Double(days), 8) / 8                // across days
            let quiet = Date().timeIntervalSince(lastSeen) / 86400
            // Decay: full weight for a fortnight, then falls away over
            // six weeks. A habit that stopped is not a habit.
            let recency = quiet <= 14 ? 1.0 : max(0, 1 - (quiet - 14) / 42)
            return min(1, (evidence * 0.5 + spread * 0.3) * (0.4 + 0.6 * recency))
        }

        /// The spec's four tiers, named rather than numbered, because a
        /// number is not something you can say out loud.
        enum Strength: String { case habit, tendency, weak, noise }
        var strength: Strength {
            if visits >= 5, days >= 3, confidence >= 0.55 { return .habit }
            if visits >= 3, confidence >= 0.35 { return .tendency }
            if visits >= 2 { return .weak }
            return .noise
        }

        /// How it gets said. Never "you always" — that is the sentence
        /// that makes an assistant sound like it is guessing, because it
        /// usually is.
        var spoken: String {
            let when: String
            if let h = hours.first {
                switch h {
                case 5...10:  when = "in the mornings"
                case 11...14: when = "around lunch"
                case 15...17: when = "in the afternoons"
                case 18...21: when = "in the evenings"
                default:      when = "late"
                }
            } else { when = "" }
            switch strength {
            case .habit:    return "you're at \(name) \(when), \(visits) times now"
            case .tendency: return "you've been to \(name) \(visits) times"
            case .weak:     return "you've been to \(name) before"
            case .noise:    return ""
            }
        }
    }

    // ---------------------------------------------------------------- read
    private static var dirURL: URL? {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first?
            .appendingPathComponent("ChappyTrail", isDirectory: true)
    }

    private static func loadVisits(days: Int) -> [DiskVisit] {
        guard let dir = dirURL else { return [] }
        let f = DateFormatter()
        f.locale = Locale(identifier: "en_US_POSIX")
        f.dateFormat = "yyyy-MM-dd"
        let cal = Calendar.current
        var out: [DiskVisit] = []
        let dec = JSONDecoder()
        dec.dateDecodingStrategy = .deferredToDate
        for back in 0..<max(1, days) {
            guard let d = cal.date(byAdding: .day, value: -back, to: Date()) else { continue }
            let u = dir.appendingPathComponent(f.string(from: d) + ".json")
            guard let data = try? Data(contentsOf: u),
                  let day = try? dec.decode(DiskDay.self, from: data),
                  let vs = day.visits else { continue }
            out.append(contentsOf: vs)
        }
        return out
    }

    /// BUILD 224 — visits inside a window, for the outcome loop.
    ///
    /// Reads the trail's files directly rather than calling ChappyTrail,
    /// which is @MainActor. That is the same reason the DiskVisit mirror
    /// above exists, and the note there applies equally here: the
    /// resolver runs from a background pass and must not hop isolation
    /// to answer "did he actually turn up".
    static func visitsBetween(_ from: Date, _ to: Date) -> [(lat: Double, lon: Double, arrive: Date)] {
        let span = max(1, Int(to.timeIntervalSince(from) / 86_400) + 2)
        return loadVisits(days: span)
            .filter { $0.arrive >= from && $0.arrive <= to }
            .map { (lat: $0.lat, lon: $0.lon, arrive: $0.arrive) }
    }

    // ---------------------------------------------------------------- build
    /// Recomputed on demand and cached for ten minutes. Ninety days of
    /// visits is a few thousand records; this is milliseconds, but it is
    /// called from a spoken path and milliseconds add up.
    // =================================================================
    // BUILD 255 — THIS IS THE CRASH. HIS REPORT SAID "CHAPPY LOOK".
    //
    // The report names it exactly:
    //
    //   EXC_BAD_ACCESS (SIGSEGV)
    //   KERN_INVALID_ADDRESS at 0x8000000000000008
    //   Thread: com.apple.root.user-initiated-qos.cooperative
    //   Top frame: swift_isUniquelyReferenced_nonNull_native
    //
    // Every part of that points at one line. `isUniquelyReferenced` is the
    // copy-on-write check Swift runs when you MUTATE a value-type container
    // — an Array. The cooperative pool means it was NOT the main thread.
    // And the address is the shape of a reference that has been released
    // underneath the caller.
    //
    // `cache` is a static Array, assigned from `habits()`, with no
    // synchronisation of any kind. `habits()` is reached from
    // `ChappyPatterns.digest()`, which is reached from
    // `ContextEngine.contextHeader()`, which QuickVisionService calls at
    // its line 206 — and QuickVisionService is a plain non-isolated class,
    // so under Swift 5 its async methods run on the cooperative pool.
    //
    // So: "chappy look" builds a vision request, the request embeds the
    // context header, the header asks for his habits, and two threads
    // reassign the same static array. GeminiLiveService and ChappyProactive
    // reach the same static from their own threads.
    //
    // A lock, and every path in and out of it goes through one door. Note
    // `loadVisits` and the clustering are done OUTSIDE the lock — they read
    // the disk and can take milliseconds, and holding a lock across that
    // would turn a crash into a stall.
    // =================================================================
    private static var cache: [Habit] = []
    private static var cachedAt = Date.distantPast
    private static let cacheLock = NSLock()

    static func habits(days: Int = 90, force: Bool = false) -> [Habit] {
        cacheLock.lock()
        let fresh = !force && Date().timeIntervalSince(cachedAt) < 600 && !cache.isEmpty
        let cached = cache
        cacheLock.unlock()
        if fresh { return cached }

        let visits = loadVisits(days: days)
        guard visits.count >= 2 else {
            cacheLock.lock(); cache = []; cachedAt = Date(); cacheLock.unlock()
            return []
        }

        // Cluster by proximity — 250 m, the same radius the Atlas uses to
        // decide two visits are the same place. Consistency matters more
        // than the exact number here.
        var clusters: [[DiskVisit]] = []
        for v in visits {
            var placed = false
            for i in clusters.indices {
                let c = clusters[i][0]
                if metres(c.lat, c.lon, v.lat, v.lon) < 250 {
                    clusters[i].append(v); placed = true; break
                }
            }
            if !placed { clusters.append([v]) }
        }

        let cal = Calendar.current
        var out: [Habit] = []
        for c in clusters where c.count >= 2 {
            let named = c.compactMap { $0.name }.first ?? "somewhere"
            let arrivals = c.map { $0.arrive }.sorted()
            let dayKeys = Set(c.map { cal.startOfDay(for: $0.arrive) })
            var hourCount: [Int: Int] = [:]
            var dayCount: [Int: Int] = [:]
            var minutes: [Int] = []
            for v in c {
                hourCount[cal.component(.hour, from: v.arrive), default: 0] += 1
                dayCount[cal.component(.weekday, from: v.arrive), default: 0] += 1
                if let d = v.depart {
                    minutes.append(max(1, Int(d.timeIntervalSince(v.arrive) / 60)))
                }
            }
            out.append(Habit(
                key: String(format: "%.3f,%.3f", c[0].lat, c[0].lon),
                name: named,
                lat: c[0].lat, lon: c[0].lon,
                visits: c.count,
                days: dayKeys.count,
                firstSeen: arrivals.first ?? Date(),
                lastSeen: arrivals.last ?? Date(),
                hours: hourCount.sorted { $0.value > $1.value }.map { $0.key },
                weekdays: dayCount.sorted { $0.value > $1.value }.map { $0.key },
                typicalMinutes: minutes.isEmpty ? nil : minutes.sorted()[minutes.count / 2]))
        }
        out.sort { $0.confidence > $1.confidence }
        cacheLock.lock()
        cache = out
        cachedAt = Date()
        cacheLock.unlock()
        return out
    }

    static func metres(_ aLat: Double, _ aLon: Double, _ bLat: Double, _ bLon: Double) -> Double {
        ChappyPorts.km(aLat, aLon, bLat, bLon) * 1000
    }

    // ---------------------------------------------------------------- ask
    /// Anything he is standing in the middle of right now.
    static func here(lat: Double, lon: Double, within: Double = 250) -> Habit? {
        habits().first { metres($0.lat, $0.lon, lat, lon) < within && $0.strength != .noise }
    }

    /// What usually happens around now, wherever he is. Used for
    /// foresight later; used for the context digest today.
    static func usualAboutNow(withinHours: Int = 1) -> [Habit] {
        let h = Calendar.current.component(.hour, from: Date())
        let wd = Calendar.current.component(.weekday, from: Date())
        return habits().filter { hab in
            guard hab.strength == .habit || hab.strength == .tendency else { return false }
            guard let top = hab.hours.first else { return false }
            let closeInTime = abs(top - h) <= withinHours
            let sameDay = hab.weekdays.first == wd
            return closeInTime || (sameDay && abs(top - h) <= 3)
        }
    }

    /// BUILD 212 — the line the brain finally gets to read.
    ///
    /// Deliberately SHORT. The spec is explicit that retrieval should be
    /// context-aware rather than dumping history into the prompt, and
    /// the fastest way to make a model worse is to bury the question
    /// under a biography.
    static func digest(lat: Double?, lon: Double?) -> String {
        let all = habits()
        guard !all.isEmpty else { return "" }
        var bits: [String] = []
        if let la = lat, let lo = lon, let h = here(lat: la, lon: lo) {
            bits.append("he is somewhere he has been \(h.visits) times before"
                        + (h.typicalMinutes.map { ", usually about \($0) minutes" } ?? ""))
        }
        let regulars = all.filter { $0.strength == .habit }.prefix(3)
        if !regulars.isEmpty {
            bits.append("places he returns to: " + regulars.map { $0.name }.joined(separator: ", "))
        }
        let now = usualAboutNow().prefix(2)
        if !now.isEmpty {
            bits.append("around this time he is often at " + now.map { $0.name }.joined(separator: " or "))
        }
        guard !bits.isEmpty else { return "" }
        // Flagged as OBSERVED, not stated. The spec's rule about never
        // presenting an inference as something he said starts here, in
        // the wording handed to the model.
        return " Observed patterns (inferred from his own movements, never confirmed by him): "
            + bits.joined(separator: "; ") + "."
    }
}


// =====================================================================
// MARK: - CHAPPY LEDGER (Build 215) — WHAT HAPPENED, AND HOW IT WENT
// =====================================================================
//
// §8 and §14. Chappy has recorded what it DID since 198 — tier, tool,
// confidence, milliseconds — in a hundred-entry buffer that dies with
// the process. What it has never recorded is what he DECIDED, or
// whether the advice turned out to be any good.
//
// Without that the loop is a line: observe, store, retrieve, reason,
// suggest, and stop. Nothing ever learns that a suggestion was
// declined nine times running, so nothing stops making it.
//
// On disk, because the point is that it survives. One JSON file,
// appended to, pruned at 500 entries — a few tens of kilobytes, and it
// is the only thing in the app that can answer "was I right last
// time?".
//
final class ChappyLedger {

    static let shared = ChappyLedger()
    private init() { load() }

    enum Kind: String, Codable {
        case suggested      // Chappy offered something
        case accepted       // he took it
        case declined       // he didn't
        case ran            // a tool executed
        case predicted      // foresight said something would happen
        case outcome        // and this is how it went
        case corrected      // he told Chappy it was wrong
    }

    struct Entry: Codable, Identifiable {
        var id = UUID()
        var at = Date()
        var kind: Kind
        /// What it was about — a tool id, a habit key, a suggestion.
        var subject: String
        /// Said out loud, so the audit reads like a diary rather than a
        /// database. §9 asks for a "what changed" that a person can read.
        var detail: String
        /// Where the belief came from. §10's provenance, on the event
        /// rather than on the memory — which is where it is actually
        /// actionable, because an event has an outcome and a fact does
        /// not.
        var source: String = "observed"
        var confidence: Double?
    }

    private(set) var entries: [Entry] = []
    private static let cap = 500

    private var url: URL? {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first?
            .appendingPathComponent("chappy_ledger.json")
    }

    private func load() {
        guard let u = url, let d = try? Data(contentsOf: u),
              let e = try? JSONDecoder().decode([Entry].self, from: d) else { return }
        entries = e
    }

    private func save() {
        guard let u = url, let d = try? JSONEncoder().encode(entries) else { return }
        try? d.write(to: u, options: .atomic)
    }

    func record(_ kind: Kind, subject: String, detail: String,
                source: String = "observed", confidence: Double? = nil) {
        entries.append(Entry(kind: kind, subject: subject, detail: detail,
                             source: source, confidence: confidence))
        if entries.count > Self.cap { entries.removeFirst(entries.count - Self.cap) }
        save()
        print("📒 [Ledger] \(kind.rawValue) · \(subject) · \(detail)")
    }

    // ---------------------------------------------------------------- ask
    /// §14: has this been offered before, and how did it go? The answer
    /// changes whether it is worth offering again.
    func record(of subject: String) -> (offered: Int, accepted: Int, declined: Int) {
        let mine = entries.filter { $0.subject == subject }
        return (mine.filter { $0.kind == .suggested }.count,
                mine.filter { $0.kind == .accepted }.count,
                mine.filter { $0.kind == .declined }.count)
    }

    /// Declined more than twice and never accepted. Stop offering it —
    /// this is the feedback the suggestion engine never had.
    func isUnwanted(_ subject: String) -> Bool {
        let r = record(of: subject)
        return r.declined >= 2 && r.accepted == 0
    }

    /// §9's "what changed?", for any window. Written to be spoken.
    func whatChanged(sinceHours hours: Int = 24) -> String {
        let cut = Date().addingTimeInterval(-Double(hours) * 3600)
        let recent = entries.filter { $0.at >= cut }
        guard !recent.isEmpty else { return "Nothing worth reporting in the last \(hours) hours." }
        let ran = recent.filter { $0.kind == .ran }.count
        let offered = recent.filter { $0.kind == .suggested }.count
        let taken = recent.filter { $0.kind == .accepted }.count
        var bits = ["\(ran) thing\(ran == 1 ? "" : "s") run"]
        if offered > 0 { bits.append("\(offered) suggested, \(taken) taken up") }
        let corrections = recent.filter { $0.kind == .corrected }
        if !corrections.isEmpty { bits.append("\(corrections.count) correction\(corrections.count == 1 ? "" : "s") from you") }
        return bits.joined(separator: ", ") + "."
    }
}

// =====================================================================
// MARK: - CHAPPY FORESIGHT (Build 215) — §7, WITH A SWITCH
// =====================================================================
//
// The spec asks for four modes and it is right to. An assistant that
// volunteers things is either useful or intolerable depending entirely
// on how often it is wrong, and that judgement is not mine to make on
// his behalf.
//
// §16 also asks for a global off switch for proactive behaviour, and it
// ships HERE, in the same build as the first proactive behaviour —
// never afterwards. Google Now is the warning: predicting well and
// explaining nothing is how a good feature becomes a creepy one.
//
// =====================================================================
// MARK: - THE OUTCOME LOOP (Build 224)
// =====================================================================
//
// The half of §14 that has never existed.
//
// `ChappyLedger` has declared `.predicted` and `.outcome` for builds and
// written neither, so nothing Chappy ever guessed was scored against
// what actually happened. An assistant that predicts and never measures
// cannot improve, and — worse — cannot know when to shut up.
//
// This is deliberately small and deliberately evidence-based. A place
// prediction resolves by asking the trail whether he actually turned up.
// No model call, nothing uploaded, works on a plane.
//
// The rule that matters most is the one about earning it: a KIND of
// prediction stays silent until it has been right often enough, over
// enough occasions, to deserve interrupting him. Google Now predicted
// eagerly from cold and died of it.
//
final class ChappyOutcomes: ObservableObject {

    static let shared = ChappyOutcomes()

    /// What sort of guess this was. Accuracy is tracked per kind, so a
    /// good place predictor is not silenced by a bad timing one.
    enum Sort: String, Codable, CaseIterable {
        case place        // "you're often at X about now"
        case timing       // "you usually leave about now"
        case need         // "you normally want Y after X"
        case deadline     // "this is about to matter"

        var spoken: String {
            switch self {
            case .place:    return "where you'd be"
            case .timing:   return "when you'd move"
            case .need:     return "what you'd want"
            case .deadline: return "what was coming up"
            }
        }
    }

    struct Prediction: Codable, Identifiable {
        var id = UUID()
        var at = Date()
        var sort: Sort
        /// What was predicted, in the words it would be said in.
        var claim: String
        /// The evidence, stated alongside — never separated from it.
        var because: String
        var confidence: Double
        /// A key the resolver can check against reality. For a place
        /// prediction this is the habit key.
        var subject: String
        /// Where, for a place prediction. Optional so the model stays
        /// decodable if a later build predicts something without a
        /// coordinate. Resolution goes by DISTANCE rather than by key
        /// string, because a habit key is the cluster's coordinate and a
        /// visit's own coordinate will never match it exactly.
        var lat: Double?
        var lon: Double?
        /// When we will know. Nothing resolves early.
        var resolveAfter: Date
        /// nil until scored.
        var hit: Bool?
        var resolvedAt: Date?
        /// True once it has actually been said out loud, so a silent
        /// prediction is not scored as if it had been offered.
        var spoken: Bool = false

        var isOpen: Bool { hit == nil }
    }

    @Published private(set) var predictions: [Prediction] = []

    private let key = "chappy_predictions_v1"
    private static let cap = 300

    private init() { load() }

    private func load() {
        guard let d = UserDefaults.standard.data(forKey: key),
              let rows = try? JSONDecoder().decode([Prediction].self, from: d)
        else { return }
        predictions = rows
    }

    private func save() {
        var rows = predictions
        if rows.count > Self.cap { rows.removeFirst(rows.count - Self.cap) }
        predictions = rows
        guard let d = try? JSONEncoder().encode(rows) else { return }
        UserDefaults.standard.set(d, forKey: key)
    }

    // ------------------------------------------------------- recording

    /// Record a guess at the moment it is made, whether or
    /// not it is ever said out loud. A prediction Chappy kept to itself
    /// still tells us whether it WOULD have been right, which is how a
    /// cold kind earns its way up to speaking.
    @discardableResult
    func predict(_ sort: Sort, claim: String, because: String,
                 confidence: Double, subject: String,
                 lat: Double? = nil, lon: Double? = nil,
                 resolvesInHours: Double = 3) -> Prediction {
        let p = Prediction(sort: sort, claim: claim, because: because,
                           confidence: confidence, subject: subject,
                           lat: lat, lon: lon,
                           resolveAfter: Date().addingTimeInterval(resolvesInHours * 3600))
        predictions.append(p)
        save()
        ChappyLedger.shared.record(.predicted, subject: subject,
                                   detail: claim, confidence: confidence)
        return p
    }

    func markSpoken(_ id: UUID) {
        guard let i = predictions.firstIndex(where: { $0.id == id }) else { return }
        predictions[i].spoken = true
        save()
    }

    // ------------------------------------------------------- resolving

    /// Score everything whose window has closed, against what the trail
    /// actually recorded. Cheap, offline, and safe to call often — it
    /// only touches predictions that are both open and due.
    func resolveDue() {
        let now = Date()
        var changed = false
        for i in predictions.indices where predictions[i].isOpen {
            let p = predictions[i]
            guard p.resolveAfter <= now else { continue }
            let hit = Self.happened(p)
            predictions[i].hit = hit
            predictions[i].resolvedAt = now
            changed = true
            ChappyLedger.shared.record(.outcome, subject: p.subject,
                                       detail: hit ? "happened: \(p.claim)"
                                                   : "didn't happen: \(p.claim)",
                                       confidence: p.confidence)
        }
        if changed { save() }
    }

    /// Did it actually happen? Evidence only — the trail's own record of
    /// where he went, which is on the phone and never uploaded.
    ///
    /// Deliberately conservative: an unresolvable prediction counts as a
    /// MISS rather than being quietly dropped. A scoring system that
    /// discards the cases it cannot judge will flatter itself forever.
    private static func happened(_ p: Prediction) -> Bool {
        switch p.sort {
        case .place, .timing:
            guard let plat = p.lat, let plon = p.lon else { return false }
            // Read the trail from DISK, not through ChappyTrail — that
            // class is @MainActor and this runs from a background pass.
            // 250 metres is the same radius the pattern engine clusters
            // at, so "he turned up" means the same thing in both places.
            let window = ChappyPatterns.visitsBetween(
                p.at.addingTimeInterval(-1800), p.resolveAfter)
            return window.contains { Self.metres(plat, plon, $0.lat, $0.lon) < 250 }
        case .need, .deadline:
            // Resolved by him acting on it — the ledger already records
            // acceptance against the same subject.
            let r = ChappyLedger.shared.record(of: p.subject)
            return r.accepted > 0
        }
    }

    /// Haversine, in metres. Local copy rather than a dependency: this
    /// runs while resolving and must never reach for anything that could
    /// be unavailable.
    private static func metres(_ aLat: Double, _ aLon: Double,
                               _ bLat: Double, _ bLon: Double) -> Double {
        let r = 6_371_000.0
        let dLat = (bLat - aLat) * .pi / 180
        let dLon = (bLon - aLon) * .pi / 180
        let a = sin(dLat / 2) * sin(dLat / 2)
            + cos(aLat * .pi / 180) * cos(bLat * .pi / 180) * sin(dLon / 2) * sin(dLon / 2)
        return r * 2 * atan2(sqrt(a), sqrt(1 - a))
    }

    // -------------------------------------------------------- scoring

    struct Score {
        let sort: Sort
        let resolved: Int
        let hits: Int
        var rate: Double { resolved == 0 ? 0 : Double(hits) / Double(resolved) }
        /// Enough evidence to act on at all.
        var settled: Bool { resolved >= 6 }
        /// Good enough to interrupt him.
        var trusted: Bool { settled && rate >= 0.55 }
        /// Bad enough to stop.
        var disgraced: Bool { resolved >= 10 && rate < 0.40 }

        var spoken: String {
            guard resolved > 0 else { return "no track record yet" }
            return "\(hits) right out of \(resolved)"
        }
    }

    func score(_ sort: Sort) -> Score {
        let mine = predictions.filter { $0.sort == sort && !$0.isOpen }
        return Score(sort: sort, resolved: mine.count,
                     hits: mine.filter { $0.hit == true }.count)
    }

    /// THE GATE. May this kind of prediction interrupt him?
    ///
    /// Three ways to fail, and all three are silence rather than a
    /// downgraded guess: not enough evidence, not accurate enough, or
    /// demonstrably bad. Nothing in this app un-learns except this.
    func mayVolunteer(_ sort: Sort) -> Bool {
        let s = score(sort)
        if s.disgraced { return false }
        return s.trusted
    }

    /// The honest report — what Chappy has guessed and how it went.
    func spokenAccuracy() -> String {
        let parts = Sort.allCases.map { sort -> String in
            let s = score(sort)
            if s.resolved == 0 { return "\(sort.spoken): nothing scored yet" }
            let verdict = s.disgraced ? " — so I've stopped saying it"
                        : (s.trusted ? "" : " — not enough to speak up on yet")
            return "\(sort.spoken): \(s.spoken)\(verdict)"
        }
        return "Here's how my guesses have gone. " + parts.joined(separator: ". ") + "."
    }
}

enum ChappyForesight {

    enum Mode: String, CaseIterable {
        case off          // says nothing, ever
        case passive      // answers only when asked
        case suggestive   // offers, once, and takes no for an answer
        case proactive    // surfaces things unprompted

        var label: String {
            switch self {
            case .off:        return "Off"
            case .passive:    return "Only when asked"
            case .suggestive: return "Offers suggestions"
            case .proactive:  return "Speaks up unprompted"
            }
        }
    }

    static var mode: Mode {
        get { Mode(rawValue: UserDefaults.standard.string(forKey: "chappy_foresight") ?? "") ?? .suggestive }
        set { UserDefaults.standard.set(newValue.rawValue, forKey: "chappy_foresight") }
    }

    /// The one line §16 insists on: everything proactive dies here.
    static var isMuted: Bool { mode == .off }

    /// What is likely, and how sure — never stated as fact. Returns nil
    /// far more often than not, which is the point.
    /// Unchanged for every existing caller: this is the ANSWER path,
    /// used when he has asked. Interrupting him is `volunteer()` below
    /// and has to be earned.
    static func anticipate() -> (line: String, confidence: Double)? {
        anticipateInner(volunteering: false)
    }

    /// BUILD 224 — the same guess, now recorded and gated.
    ///
    /// `volunteering` is the difference between answering a question and
    /// interrupting him. Answering is always allowed if the mode permits
    /// it; interrupting has to be earned by a measured track record.
    static func anticipateInner(volunteering: Bool) -> (line: String, confidence: Double)? {
        guard mode == .suggestive || mode == .proactive else { return nil }
        if volunteering, mode != .proactive { return nil }

        let likely = ChappyPatterns.usualAboutNow()
        guard let top = likely.first, top.strength == .habit else { return nil }
        let c = top.confidence
        guard c >= 0.55 else { return nil }

        // §2 and §10: the reason travels with the prediction, and the
        // wording never claims he said it.
        let because = "\(top.visits) times so far"
        let line = "You're often at \(top.name) about now — \(because). Want it?"

        // Recorded whether or not it is said. A prediction Chappy keeps
        // to itself still tells us whether it WOULD have been right,
        // which is how a cold kind earns its way up to speaking.
        let p = ChappyOutcomes.shared.predict(
            .place, claim: "at \(top.name)", because: because,
            confidence: c,
            subject: top.key,
            lat: top.lat, lon: top.lon,
            resolvesInHours: 3)

        // THE GATE. Interrupting him requires a track record; answering
        // a direct question does not.
        if volunteering, !ChappyOutcomes.shared.mayVolunteer(.place) { return nil }

        ChappyOutcomes.shared.markSpoken(p.id)
        return (line, c)
    }

    /// What Chappy would say unprompted, if it has earned the right.
    /// Returns nil far more often than not, which is the point.
    static func volunteer() -> (line: String, confidence: Double)? {
        ChappyOutcomes.shared.resolveDue()
        return anticipateInner(volunteering: true)
    }
}
